def fmt_int(x):
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x): return ""
    return f"{x:.0f}"

def fmt_count_1(x):
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x): return ""
    return f"{x:.1f}"

def fmt_rate_3(x):
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x): return ""
    return f"{x:.3f}"

def fmt_rate_4(x):
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x): return ""
    return f"{x:.4f}"


def fmt_score_2(x):
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x):
        return ""
    return f"{x:.2f}"


def fmt_fantasy_edge(x):
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x):
        return ""
    return f"{int(round(x)):+d}"


def fmt_score_1(x):
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x):
        return ""
    return f"{x:.1f}".rstrip("0").rstrip(".")


def fmt_player_grade_display(x):
    try:
        from draft_score_display import fmt_player_grade

        return fmt_player_grade(x)
    except ImportError:
        return fmt_rate_4(x)


def fmt_pick_score_display(x):
    try:
        from draft_score_display import fmt_pick_score

        return fmt_pick_score(x)
    except ImportError:
        return fmt_score_2(x)


def fmt_ml_projection_score_display(x):
    try:
        from draft_score_display import fmt_ml_projection_score

        return fmt_ml_projection_score(x)
    except ImportError:
        return fmt_score_2(x)


def fmt_rate_dot(x):
    """Rate stat for display: four decimals, leading dot when below 1.000."""
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x):
        return ""
    s = f"{x:.4f}"
    if x < 1 and x >= 0 and s.startswith("0."):
        return s[1:]
    if x > -1 and x < 0 and s.startswith("-0."):
        return "-" + s[2:]
    return s


def fmt_percent_1(x):
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x):
        return ""
    if abs(x) <= 1.5:
        x = x * 100
    return f"{x:.1f}%"


def _draft_lab_column_kind(col):
    """Classify a draft-lab column for consistent numeric formatting."""
    name = str(col)
    low = name.lower()
    if name in {"Round", "Pick", "Players", "Have", "Target", "Gap", "Projected Team Rank", "Actual Rank"}:
        return "int"
    if name in {"Market Rank", "Model Rank", "FantasyPros Rank", "ADP Rank", "Current Rank"} or low.endswith(" rank"):
        return "int"
    if name in ("Projection Confidence", "Projection Confidence Score"):
        return "confidence"
    if "fantasy edge" in low:
        return "edge"
    if low.endswith("probability") or "percent" in low or low.endswith(" pct") or name == "Projection Confidence Score":
        return "percent"
    if name in {
        "Player Grade", "Pick Score", "Total Player Grade", "Average Player Grade",
        "Draft Lab Team Score",
        "Relative Draft Grade",
        "Expected Fantasy Value", "Total Projected Fantasy Value", "Decision Score", "Draft Fit Score",
        "Positional Fit", "Recommendation Score", "Sleeper Score",
        "Scarcity Score", "Best Player Available Score", "Best Value Sleeper Score", "Blended Projection Score",
        "ML Projection Score", "App Ranking Score", "Actual Draft Score", "Elite Star Score",
        "Roster Need Improvement", "Projected Value Gain/Loss", "Average Scarcity Score",
        "Average Expected Fantasy Value",
    }:
        return "score2"
    if low in {"ba", "obp", "slg", "ops"} or "projected avg" in low or "projected obp" in low or "projected slg" in low or "projected ops" in low:
        return "rate"
    if low.startswith("proj_") and low.split("_", 1)[-1] in {"ba", "obp", "slg", "ops"}:
        return "rate"
    if low.startswith("proj_") and low.split("_", 1)[-1] in {"hr", "rbi", "r", "sb", "g", "pa", "ab", "bb", "h", "2b", "3b"}:
        return "count"
    if low.startswith("projected "):
        stat = low.replace("projected ", "", 1)
        if stat in {
            "hr", "rbi", "r", "sb", "g", "pa", "ab", "bb", "h", "2b", "3b",
            "w", "sv", "k", "ip", "era", "whip",
        }:
            return "count"
        if stat in {"avg", "obp", "slg", "ops"}:
            return "rate"
    if low.startswith("actual ") and low.split()[-1] in {"hr", "rbi", "r", "sb"}:
        return "count"
    if low.startswith("actual ") and low.endswith("ops"):
        return "rate"
    return None


def format_draft_lab_table(df, for_export=False):
    """Polished numeric formatting for Draft Lab / Simulation tables and exports."""
    if df is None or df.empty:
        return df
    try:
        from draft_score_display import (
            normalize_projection_confidence_column,
            normalize_projection_warning_column,
            prepare_draft_scores_for_display,
        )

        df = normalize_projection_confidence_column(df)
        df = normalize_projection_warning_column(df)
        df = prepare_draft_scores_for_display(df)
    except ImportError:
        pass
    out = df.copy()
    for col in out.columns:
        kind = _draft_lab_column_kind(col)
        if kind is None:
            continue
        vals = pd.to_numeric(out[col], errors="coerce")
        if kind == "int":
            out[col] = vals.round(0).astype("Int64")
        elif kind == "edge":
            out[col] = vals.apply(fmt_fantasy_edge)
        elif kind == "confidence":
            try:
                from draft_score_display import fmt_confidence_score

                out[col] = vals.apply(fmt_confidence_score)
            except ImportError:
                out[col] = vals.round(2)
        elif kind == "score2":
            if "roster fit" in str(col).lower():
                try:
                    from draft_score_display import fmt_roster_fit_score

                    out[col] = vals.apply(fmt_roster_fit_score)
                except ImportError:
                    out[col] = vals.round(2)
            elif "decision score" in str(col).lower() or str(col) == "Decision Score":
                out[col] = vals.apply(fmt_score_2)
            elif "player grade" in str(col).lower() or "expected fantasy" in str(col).lower():
                out[col] = vals.apply(fmt_score_1)
            else:
                out[col] = vals.apply(fmt_score_2) if for_export else vals.round(2)
        elif kind == "percent":
            out[col] = vals.apply(fmt_percent_1)
        elif kind == "rate":
            out[col] = vals.apply(fmt_rate_dot) if for_export else vals.round(4)
        else:  # count
            out[col] = vals.apply(fmt_count_1) if for_export else vals.round(1)
    return out


def format_team_projected_totals_table(df, *, for_export: bool = True):
    """Format team projected totals: 1 decimal for counting stats, 4-decimal dot style for AVG/OPS."""
    return format_draft_lab_table(df, for_export=for_export)


def _is_team_projected_totals_table_key(key: str) -> bool:
    return str(key) in {"live_draft_team_totals", "draft_lab_team_analysis"}


def _draft_lab_styler_format(display_df):
    """Pandas Styler format map for draft-lab tables."""
    fmt = {}
    for col in display_df.columns:
        kind = _draft_lab_column_kind(col)
        if kind == "percent":
            continue
        if kind == "edge":
            fmt[col] = "{:+.1f}"
        elif kind == "score2":
            fmt[col] = "{:.2f}"
        elif kind == "count":
            fmt[col] = "{:.1f}"
        elif kind == "rate":
            fmt[col] = fmt_rate_dot
        elif kind == "percent":
            fmt[col] = "{:.1f}%"
        elif kind == "int":
            fmt[col] = "{:.0f}"
    return fmt


def normalize_series(series):
    """Scale a numeric pandas Series to 0-1 safely.

    Used by the fantasy and draft assistant pages so different stats
    can be combined into one score without crashing on missing values,
    all-equal values, or non-numeric data.
    """
    s = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan)
    if s.notna().sum() == 0:
        return pd.Series(0.0, index=series.index)
    s = s.fillna(s.median())
    min_val = s.min()
    max_val = s.max()
    if pd.isna(min_val) or pd.isna(max_val) or max_val == min_val:
        return pd.Series(0.0, index=series.index)
    return (s - min_val) / (max_val - min_val)


def safe_numeric_series(df, col, default=0.0):
    """Return a numeric Series for ``col`` with an index-aligned fallback."""
    if col in df.columns:
        return pd.to_numeric(df[col], errors="coerce").fillna(default)
    return pd.Series(default, index=df.index, dtype="float64")


def safe_round_rate_stats(df):
    df = df.copy()
    for col in ["BA", "OBP", "SLG", "OPS", "BA_roll", "OBP_roll", "SLG_roll", "OPS_roll"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce").round(3)
    return df



def build_clean_player_label_map(df):
    """Build clean player dropdown labels without Lahman/playerID text.

    If names are duplicated, append a short career span rather than the internal ID.
    """
    base = (
        df[["playerID", "fullName", "yearID"]]
        .dropna(subset=["playerID", "fullName"])
        .copy()
    )
    base["yearID"] = pd.to_numeric(base["yearID"], errors="coerce")
    spans = base.groupby(["playerID", "fullName"], as_index=False)["yearID"].agg(["min", "max"]).reset_index()
    name_counts = spans["fullName"].value_counts().to_dict()

    label_map = {}
    for _, row in spans.sort_values(["fullName", "min", "max"]).iterrows():
        name = str(row["fullName"])
        if name_counts.get(name, 0) > 1:
            label = f"{name} ({int(row['min'])}-{int(row['max'])})"
        else:
            label = name
        label_map[label] = row["playerID"]
    return label_map


def get_player_career_span(df, player_id):
    player_years = pd.to_numeric(df.loc[df["playerID"] == player_id, "yearID"], errors="coerce").dropna()
    if player_years.empty:
        all_years = pd.to_numeric(df["yearID"], errors="coerce").dropna()
        return int(all_years.min()), int(all_years.max())
    return int(player_years.min()), int(player_years.max())


def player_last_name(full_name):
    parts = str(full_name).strip().split()
    return parts[-1] if parts else str(full_name)


def _compare_available_year_range(df, player_ids):
    if not player_ids:
        return None
    years = pd.to_numeric(df.loc[df["playerID"].isin(player_ids), "yearID"], errors="coerce").dropna()
    if years.empty:
        return None
    return int(years.min()), int(years.max())


def _is_full_compare_year_range(df, player_ids, compare_year_range):
    avail = _compare_available_year_range(df, player_ids)
    if avail is None:
        return True
    try:
        lo, hi = int(compare_year_range[0]), int(compare_year_range[1])
    except Exception:
        return True
    return (lo, hi) == avail


def _compare_sig_sync_caption(compare_x_axis_mode, compare_year_range, compare_age_range, df, player_ids):
    if compare_x_axis_mode == "Player Age":
        return f"Synced to comparison age range: {int(compare_age_range[0])}–{int(compare_age_range[1])}"
    if _is_full_compare_year_range(df, player_ids, compare_year_range):
        return "Using full available career range"
    return f"Synced to comparison year range: {int(compare_year_range[0])}–{int(compare_year_range[1])}"


def _compare_sig_player_range_tuple(
    career_min,
    career_max,
    *,
    compare_x_axis_mode,
    compare_year_range,
    compare_age_range,
    use_full_career,
):
    if compare_x_axis_mode == "Player Age":
        return int(compare_age_range[0]), int(compare_age_range[1])
    if use_full_career:
        return int(career_min), int(career_max)
    return max(int(career_min), int(compare_year_range[0])), min(int(career_max), int(compare_year_range[1]))


def _format_sig_range_display(range_tuple):
    return f"{int(range_tuple[0])}–{int(range_tuple[1])}"


def _compare_sig_range_column_label(last_name, compare_x_axis_mode):
    suffix = "ages" if compare_x_axis_mode == "Player Age" else "years"
    return f"{last_name} {suffix}"


def _attach_season_age_column(df):
    out = df.copy()
    out["Age"] = out.apply(
        lambda r: baseball_age_for_season(
            r.get("yearID"),
            r.get("birthYear", np.nan),
            r.get("birthMonth", np.nan),
            r.get("birthDay", np.nan),
        ),
        axis=1,
    )
    return out


def _filter_player_seasons_for_sig(df, player_id, compare_x_axis_mode, range_tuple):
    data = df[df["playerID"] == player_id].copy()
    if compare_x_axis_mode == "Season Year":
        years = pd.to_numeric(data["yearID"], errors="coerce")
        return data[(years >= range_tuple[0]) & (years <= range_tuple[1])].copy()
    data = _attach_season_age_column(data)
    ages = pd.to_numeric(data["Age"], errors="coerce")
    return data[(ages >= range_tuple[0]) & (ages <= range_tuple[1])].copy()


def build_pid_to_clean_label_map(df):
    label_map = build_clean_player_label_map(df)
    return {pid: label for label, pid in label_map.items()}


def resolve_fullname_to_clean_label(full_name, label_map):
    """Map a table/full name string to the app's canonical dropdown label (handles duplicate names with career spans)."""
    fn = " ".join(str(full_name).strip().split())
    if not fn:
        return None
    if fn in label_map:
        return fn
    base = " ".join(fullname_base_from_label(fn).split())
    if base in label_map:
        return base
    # Legacy team-suffix labels from older saves, e.g. "Juan Soto (NYY)".
    if fn.endswith(")") and "(" in fn:
        suffix = fn[fn.rfind("(") + 1 : -1].strip()
        if suffix.isupper() and 2 <= len(suffix) <= 4:
            base_from_team = fn[: fn.rfind("(")].strip()
            if base_from_team in label_map:
                return base_from_team
            base_matches = [
                lbl for lbl in label_map.keys() if fullname_base_from_label(lbl) == base_from_team
            ]
            if len(base_matches) == 1:
                return base_matches[0]
            if len(base_matches) > 1:
                return sorted(base_matches)[0]
            resolved = resolve_fullname_to_clean_label(base_from_team, label_map)
            if resolved:
                return resolved
    candidates = sorted([lbl for lbl in label_map.keys() if lbl.startswith(fn + " (")])
    if candidates:
        return candidates[0]
    candidates = sorted([lbl for lbl in label_map.keys() if lbl.startswith(base + " (")])
    if candidates:
        return candidates[0]
    base_matches = [lbl for lbl in label_map.keys() if fullname_base_from_label(lbl) == base]
    if len(base_matches) == 1:
        return base_matches[0]
    if len(base_matches) > 1:
        return sorted(base_matches)[0]
    fl = fn.lower()
    bl = base.lower()
    ci = [lbl for lbl in label_map.keys() if str(lbl).lower() == fl or fullname_base_from_label(lbl).lower() == bl]
    if len(ci) == 1:
        return ci[0]
    return None


def fullname_base_from_label(label):
    return str(label).split(" (")[0].strip()


def _canonical_draft_board_df():
    """Single source of truth for drafted players across the app."""
    try:
        from draft_room_state import get_canonical_draft_board

        return get_canonical_draft_board(st.session_state)
    except Exception:
        try:
            from draft_room_state import coerce_board_table

            return coerce_board_table(st.session_state.get("draft_room_table"))
        except Exception:
            return pd.DataFrame(columns=["Round", "Pick", "Team", "Player"])


def _session_draft_board_df():
    """Coerce session draft_room_table to DataFrame (safe after cloud/disk blob restore)."""
    try:
        from draft_room_state import (
            ensure_live_draft_synced_to_canonical_board,
            ensure_runtime_draft_board,
            prepare_draft_room_state,
        )

        ensure_live_draft_synced_to_canonical_board(st.session_state, reason="session_draft_board_df")
        prepare_draft_room_state(st.session_state)
        return ensure_runtime_draft_board(st.session_state)
    except Exception:
        return _canonical_draft_board_df()


def get_next_open_draft_pick_team():
    """Team whose row has the next empty Player slot in Draft Room table pick order."""
    table = _canonical_draft_board_df()
    if table.empty or "Player" not in table.columns or "Team" not in table.columns:
        return None
    t = table.copy()
    open_mask = t["Player"].fillna("").astype(str).str.strip().eq("")
    if not open_mask.any():
        return None
    if "Pick" in t.columns:
        t = t.sort_values("Pick", kind="stable")
    for _, row in t.iterrows():
        if str(row.get("Player", "")).strip() == "":
            return str(row.get("Team", "")).strip()
    return None


def is_users_draft_turn(team_name):
    """True when Draft Room's next open pick belongs to team_name."""
    if team_name is None or str(team_name).strip() == "":
        return False
    nxt = get_next_open_draft_pick_team()
    if nxt is None:
        return False
    return str(nxt).strip() == str(team_name).strip()


def register_players_sent_to_trend_page(full_name, label_map):
    """Queue one player for Trend Value (single dashboard + up to 3 on multi chart).

    Returns (success, user-facing message).
    """
    lbl = resolve_fullname_to_clean_label(full_name, label_map)
    if not lbl:
        return False, "Could not match that name in the database."

    valid = _valid_trend_chart_labels([lbl], label_map)
    if not valid:
        display = fullname_base_from_label(lbl)
        return (
            False,
            f"{display} does not have enough recent seasons for a trend chart. "
            "Try a player with more recent playing time.",
        )

    chart_lbl = valid[0]
    base_fn = fullname_base_from_label(chart_lbl)

    if not st.session_state.get("trend_anchor_fullname"):
        st.session_state["trend_anchor_fullname"] = base_fn

    mq = st.session_state.get("trend_multi_queue_fullnames", [])
    if not isinstance(mq, list):
        mq = []
    if base_fn in mq:
        mq.remove(base_fn)
    mq.append(base_fn)
    while len(mq) > 12:
        mq.pop(0)
    st.session_state["trend_multi_queue_fullnames"] = mq

    anchor = st.session_state.get("trend_anchor_fullname") or base_fn
    anchor_label = resolve_fullname_to_clean_label(anchor, label_map)
    if anchor_label and anchor_label in label_map:
        valid_anchor = _valid_trend_chart_labels([anchor_label], label_map)
        anchor_label = valid_anchor[0] if valid_anchor else chart_lbl
    else:
        anchor_label = chart_lbl

    multi_labels = []
    for name in mq:
        ml = resolve_fullname_to_clean_label(name, label_map)
        if not ml:
            continue
        ok = _valid_trend_chart_labels([ml], label_map)
        if ok and ok[0] not in multi_labels:
            multi_labels.append(ok[0])

    if chart_lbl not in multi_labels:
        multi_labels = plr_act.merge_chart_labels(multi_labels, chart_lbl, max_labels=3)
    else:
        multi_labels = plr_act.merge_chart_labels(multi_labels, chart_lbl, max_labels=3)

    st.session_state["trend_force_single_label"] = anchor_label
    st.session_state["trend_force_multi_labels"] = multi_labels[:3]
    st.session_state["trend_players_multi"] = multi_labels[:3]
    st.session_state["single_trend_dashboard_player"] = anchor_label
    st.session_state["pending_trend_players"] = [fullname_base_from_label(x) for x in multi_labels[:3]]
    st.session_state["pending_trend_player"] = fullname_base_from_label(anchor_label)
    display = fullname_base_from_label(chart_lbl)
    return True, f"Sent {display} to Trends."


def append_compare_player_ordered(full_name, label_map):
    """Queue one player for the Comparison Tool using Player A / Player B slots."""
    try:
        from comparison_state import (
            gather_comparison_players,
            normalize_compare_label,
            write_canonical_comparison_state,
        )
    except ImportError:
        gather_comparison_players = None  # type: ignore[assignment]

    lbl = resolve_fullname_to_clean_label(full_name, label_map)
    if not lbl:
        return False

    if gather_comparison_players is not None:
        current = gather_comparison_players(st.session_state, label_map, resolve_fullname_to_clean_label)
        a = current[0] if len(current) >= 1 else None
        b = current[1] if len(current) >= 2 else None
        if not a:
            return bool(write_canonical_comparison_state(st.session_state, [lbl], reason="send_player_a"))
        if a == lbl:
            return True
        if not b or b == lbl:
            return bool(write_canonical_comparison_state(st.session_state, [a, lbl], reason="send_player_b"))
        return bool(write_canonical_comparison_state(st.session_state, [a, lbl], reason="send_replace_b"))

    a = st.session_state.get("sig_player_a_clean")
    b = st.session_state.get("sig_player_b_clean")
    a = a if isinstance(a, str) and a in label_map else None
    b = b if isinstance(b, str) and b in label_map else None

    old_compare = [x for x in (st.session_state.get("compare_players") or []) if isinstance(x, str) and x in label_map]
    if a is None and old_compare:
        a = old_compare[0]
    if b is None and len(old_compare) > 1:
        b = old_compare[1]

    if not a:
        st.session_state["pending_sig_player_a"] = lbl
        st.session_state["pending_compare_clear_player_b"] = True
        st.session_state.pop("pending_sig_player_b", None)
        tail = [x for x in old_compare if x != lbl]
        st.session_state["pending_compare_players"] = ([lbl] + tail)[:3]
        return True

    if a == lbl:
        tail = [x for x in old_compare if x != lbl]
        st.session_state["pending_compare_players"] = ([lbl] + tail)[:3]
        return True

    if not b or b == lbl:
        st.session_state["pending_sig_player_b"] = lbl
        merged = [a, lbl]
        for x in old_compare:
            if x not in merged and len(merged) < 3:
                merged.append(x)
        st.session_state["pending_compare_players"] = merged[:3]
        return True

    st.session_state["pending_sig_player_a"] = a
    st.session_state["pending_sig_player_b"] = lbl
    merged = [a, lbl]
    for x in old_compare:
        if x not in merged and len(merged) < 3:
            merged.append(x)
    st.session_state["pending_compare_players"] = merged[:3]
    return True


def build_player_label_map(df):
    options = df[["playerID", "fullName"]].drop_duplicates().sort_values(["fullName", "playerID"])
    return {f"{row.fullName} ({row.playerID})": row.playerID for row in options.itertuples()}



def plot_player_stat_trends(ax, df, player_ids, stat_col, mode="Actual Values", smooth_window=3):
    """Plot one stat for multiple players using actual values or a moving-average smooth."""
    for pid in player_ids:
        subset = df[df["playerID"] == pid].sort_values("yearID").copy()
        if subset.empty or stat_col not in subset.columns:
            continue

        player_name = subset["fullName"].iloc[0] if "fullName" in subset.columns else str(pid)
        y = pd.to_numeric(subset[stat_col], errors="coerce")

        if mode == "Smoothed Moving Average":
            y_plot = y.rolling(window=int(smooth_window), min_periods=1).mean()
            label = f"{player_name} — smoothed"
        else:
            y_plot = y
            label = player_name

        ax.plot(subset["yearID"], y_plot, marker="o", label=label)




def _trend_numeric_series(df, stat_col):
    if df is None or df.empty or stat_col not in df.columns:
        return pd.Series(dtype=float), pd.Series(dtype=float)
    d = df.sort_values("yearID").copy()
    x = pd.to_numeric(d["yearID"], errors="coerce")
    y = pd.to_numeric(d[stat_col], errors="coerce")
    mask = x.notna() & y.notna()
    return x[mask], y[mask]


def _trend_slope_r2(x, y):
    if len(x) < 2 or len(y) < 2:
        return np.nan, np.nan
    try:
        coef = np.polyfit(x.astype(float), y.astype(float), 1)
        pred = coef[0] * x.astype(float) + coef[1]
        ss_res = float(((y.astype(float) - pred) ** 2).sum())
        ss_tot = float(((y.astype(float) - y.astype(float).mean()) ** 2).sum())
        r2 = np.nan if ss_tot == 0 else 1 - ss_res / ss_tot
        return float(coef[0]), float(r2)
    except Exception:
        return np.nan, np.nan


def classify_player_trend_from_series(x, y, stat_col):
    """Classify a player trend using slope, recent slope, volatility, and direction."""
    if len(y) < 3:
        return {
            "Trend Direction": "Not enough data",
            "Slope": np.nan,
            "Recent Slope": np.nan,
            "Volatility": np.nan,
            "Consistency Rating": "Unknown",
            "R²": np.nan,
            "Fantasy Signal": "Not enough recent seasons to classify."
        }

    slope, r2 = _trend_slope_r2(x, y)
    recent_x = x.tail(min(3, len(x)))
    recent_y = y.tail(min(3, len(y)))
    recent_slope, _ = _trend_slope_r2(recent_x, recent_y)

    volatility = float(y.std()) if len(y) > 1 else np.nan
    mean_abs = float(abs(y.mean())) if pd.notna(y.mean()) else np.nan
    cv = volatility / mean_abs if mean_abs and mean_abs != 0 else np.nan

    if pd.isna(cv):
        consistency = "Unknown"
    elif cv < 0.12:
        consistency = "Very consistent"
    elif cv < 0.25:
        consistency = "Moderately consistent"
    elif cv < 0.45:
        consistency = "Volatile"
    else:
        consistency = "Very volatile"

    # Stat-aware thresholds: rate stats need smaller slope cutoffs than counting stats.
    rate_stats = {"BA", "AVG", "OBP", "SLG", "OPS", "BB%", "K%", "Strikeout Rate", "Walk Rate"}
    if str(stat_col).upper() in {s.upper() for s in rate_stats}:
        strong = 0.015
        mild = 0.005
    else:
        strong = 4.0
        mild = 1.0

    if pd.isna(slope):
        direction = "Not enough data"
    elif slope >= strong:
        direction = "Accelerating upward" if pd.notna(recent_slope) and recent_slope > slope * 1.20 else "Improving"
    elif slope >= mild:
        direction = "Slightly improving"
    elif slope <= -strong:
        direction = "Accelerating downward" if pd.notna(recent_slope) and recent_slope < slope * 1.20 else "Declining"
    elif slope <= -mild:
        direction = "Slightly declining"
    else:
        direction = "Stable"

    fantasy_signal = "Stable profile."
    if direction in ["Improving", "Accelerating upward"] and consistency in ["Very consistent", "Moderately consistent"]:
        fantasy_signal = "Positive fantasy momentum with relatively reliable year-to-year growth."
    elif direction in ["Improving", "Accelerating upward"] and consistency in ["Volatile", "Very volatile"]:
        fantasy_signal = "Upside signal, but volatility means the breakout may carry risk."
    elif direction in ["Declining", "Accelerating downward"]:
        fantasy_signal = "Possible decline or bust-risk signal."
    elif consistency in ["Very consistent", "Moderately consistent"]:
        fantasy_signal = "Consistency may be useful even without a major breakout trend."
    elif consistency in ["Volatile", "Very volatile"]:
        fantasy_signal = "High volatility; treat recent spikes carefully."

    return {
        "Trend Direction": direction,
        "Slope": slope,
        "Recent Slope": recent_slope,
        "Volatility": volatility,
        "Consistency Rating": consistency,
        "R²": r2,
        "Fantasy Signal": fantasy_signal
    }


def build_advanced_trend_intelligence(df, player_ids, stat_col):
    rows = []
    for pid in player_ids:
        sub = df[df["playerID"] == pid].sort_values("yearID").copy()
        if sub.empty:
            continue
        player = sub["fullName"].iloc[0] if "fullName" in sub.columns else str(pid)
        x, y = _trend_numeric_series(sub, stat_col)
        info = classify_player_trend_from_series(x, y, stat_col)
        last_val = y.iloc[-1] if len(y) else np.nan
        first_val = y.iloc[0] if len(y) else np.nan
        info.update({
            "Player": player,
            "Stat": stat_col,
            "First Value": first_val,
            "Latest Value": last_val,
            "Net Change": last_val - first_val if pd.notna(last_val) and pd.notna(first_val) else np.nan,
            "Years Used": (float(x.iloc[-1]) - float(x.iloc[0])) if len(x) >= 2 else 0
        })
        rows.append(info)
    out = pd.DataFrame(rows)
    if not out.empty and "Slope" in out.columns:
        out = out.sort_values("Slope", ascending=False)
    return out


def make_advanced_trend_commentary(intel_df, stat_col):
    if intel_df is None or intel_df.empty:
        return "Not enough data to generate trend intelligence."

    lines = []
    best = intel_df.sort_values("Slope", ascending=False).iloc[0]
    worst = intel_df.sort_values("Slope", ascending=True).iloc[0]

    if pd.notna(best.get("Slope")):
        lines.append(
            f"{best['Player']} shows the strongest {stat_col} growth trend in this comparison "
            f"(slope {best['Slope']:.2f} per season, {best.get('Trend Direction', 'trend unclear').lower()})."
        )

    if len(intel_df) > 1 and pd.notna(worst.get("Slope")) and worst["Player"] != best["Player"]:
        lines.append(
            f"{worst['Player']} has the weakest {stat_col} trend here "
            f"(slope {worst['Slope']:.2f} per season, {worst.get('Trend Direction', 'trend unclear').lower()})."
        )

    volatile = intel_df[intel_df["Consistency Rating"].astype(str).str.contains("volatile", case=False, na=False)]
    if not volatile.empty:
        v = volatile.iloc[0]
        lines.append(
            f"{v['Player']} has a higher volatility profile, so recent spikes should be treated more cautiously."
        )

    consistent = intel_df[intel_df["Consistency Rating"].astype(str).str.contains("consistent", case=False, na=False)]
    if not consistent.empty:
        c = consistent.iloc[0]
        lines.append(
            f"{c['Player']} grades as {str(c['Consistency Rating']).lower()}, which is useful for fantasy managers who prefer stable production."
        )

    if not lines:
        lines.append("The selected players have similar or unclear trend patterns.")

    return " ".join(lines)


def round_trend_delta_frame(df):
    """Round per-season slope (Δ) columns to 2 decimals for display and export."""
    out = df.copy()
    for col in ALL_TREND_DELTA_COLS:
        if col in out.columns:
            out[col] = pd.to_numeric(out[col], errors="coerce").round(2)
    return out


def format_trimmed_2dp(value):
    """Round to 2 decimals and strip trailing zeros (1.50 -> 1.5, 2.00 -> 2)."""
    try:
        if pd.isna(value):
            return ""
        s = f"{float(value):.2f}".rstrip("0").rstrip(".")
        if s == "-0":
            s = "0"
        if s.startswith("."):
            s = "0" + s
        if s.startswith("-."):
            s = s.replace("-.", "-0.", 1)
        return s
    except Exception:
        return value


TREND_VOLATILITY_COLS = ["Volatility"]


def format_advanced_trend_table(df):
    out = df.copy()
    for c in TREND_SLOPE_COLS:
        if c in out.columns:
            out[c] = pd.to_numeric(out[c], errors="coerce").round(2)
    for c in TREND_VOLATILITY_COLS:
        if c in out.columns:
            out[c] = out[c].apply(format_trimmed_2dp)
    for c in ["First Value", "Latest Value", "Net Change"]:
        if c in out.columns:
            out[c] = pd.to_numeric(out[c], errors="coerce").round(4)
    if "R²" in out.columns:
        out["R²"] = pd.to_numeric(out["R²"], errors="coerce").round(4)
    if "Years Used" in out.columns:
        out["Years Used"] = pd.to_numeric(out["Years Used"], errors="coerce").round(0).astype("Int64")
    out = out.rename(columns={"Trend Direction": "Trend", "R²": "R-squared"})
    ordered_cols = [
        "Player",
        "Stat",
        "Slope",
        "Trend",
        "Recent Slope",
        "Volatility",
        "Consistency Rating",
        "R-squared",
        "Fantasy Signal",
        "First Value",
        "Latest Value",
        "Net Change",
        "Years Used",
    ]
    return out[[c for c in ordered_cols if c in out.columns]]


def compute_trend_slope(group, stat_col):
    group = group.sort_values("yearID")
    x = pd.to_numeric(group["yearID"], errors="coerce").values
    y = pd.to_numeric(group[stat_col], errors="coerce").values
    mask = ~pd.isna(y)
    x = x[mask]
    y = y[mask]
    if len(x) < 2:
        return np.nan
    return np.polyfit(x, y, 1)[0]


@st.cache_data(show_spinner=False)
def compute_player_trend_table(recent_data, stats_tuple):
    """Cached per-player trend slopes reused by Trend, Valuation, Draft, and Sleepers pages."""
    stats = [s for s in (stats_tuple or []) if recent_data is not None and s in recent_data.columns]
    cols = ["playerID"] + [f"{s}_trend" for s in stats]
    if recent_data is None or recent_data.empty or "playerID" not in recent_data.columns:
        return pd.DataFrame(columns=cols)
    src = recent_data[["playerID", "yearID"] + stats].copy()

    def _slopes(g):
        return pd.Series({f"{stat}_trend": compute_trend_slope(g, stat) for stat in stats})

    grouped = src.groupby("playerID", group_keys=False)
    try:
        out = grouped.apply(_slopes, include_groups=False).reset_index()
    except TypeError:
        out = grouped.apply(_slopes).reset_index()
    if out.columns.duplicated().any():
        out = out.loc[:, ~out.columns.duplicated()]
    return out


@st.cache_data(show_spinner=False)
def get_latest_player_context(recent_data, cols_tuple):
    """Latest season context by player, cached to avoid repeated sorting/groupby work."""
    cols = [c for c in (cols_tuple or []) if recent_data is not None and c in recent_data.columns]
    if recent_data is None or recent_data.empty or "playerID" not in recent_data.columns:
        return pd.DataFrame(columns=cols)
    latest = recent_data.sort_values(["playerID", "yearID"]).groupby("playerID").tail(1)[cols].copy()
    if {"yearID", "birthYear"}.issubset(latest.columns):
        latest["Age"] = latest.apply(
            lambda r: baseball_age_for_season(
                r.get("yearID"),
                r.get("birthYear"),
                r.get("birthMonth", np.nan),
                r.get("birthDay", np.nan),
            ),
            axis=1,
        )
    return latest


@st.cache_data(show_spinner=False)
def aggregate_recent_player_totals(recent_data, stat_cols_tuple):
    """Cached player totals over a selected recent-season window."""
    if recent_data is None or recent_data.empty:
        return pd.DataFrame()
    group_cols = [c for c in ["playerID", "fullName", "bats"] if c in recent_data.columns]
    stat_cols = [c for c in (stat_cols_tuple or []) if c in recent_data.columns]
    if not group_cols or not stat_cols:
        return pd.DataFrame()
    out = recent_data.groupby(group_cols, as_index=False)[stat_cols].sum()
    return add_rate_stats(out)

def add_missing_numeric_columns(df, cols):
    df = df.copy()
    for col in cols:
        if col not in df.columns:
            df[col] = 0
        df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0)
    return df

def add_rate_stats(df):
    df = df.copy()
    needed_cols = ["AB", "H", "2B", "3B", "HR", "BB", "HBP", "SF"]
    df = add_missing_numeric_columns(df, needed_cols)
    df["1B"] = df["H"] - df["2B"] - df["3B"] - df["HR"]
    ab_denom = df["AB"].replace(0, np.nan)
    obp_denom = (df["AB"] + df["BB"] + df["HBP"] + df["SF"]).replace(0, np.nan)
    df["BA"] = pd.to_numeric(df["H"] / ab_denom, errors="coerce")
    df["OBP"] = pd.to_numeric((df["H"] + df["BB"] + df["HBP"]) / obp_denom, errors="coerce")
    df["SLG"] = pd.to_numeric((df["1B"] + 2 * df["2B"] + 3 * df["3B"] + 4 * df["HR"]) / ab_denom, errors="coerce")
    df["OPS"] = pd.to_numeric(df["OBP"] + df["SLG"], errors="coerce")
    return df

def apply_stat_min_filters(df, prefix, on_change=None):
    df = df.copy()
    stat_columns = ["R", "AB", "H", "2B", "3B", "HR", "RBI", "SB", "BB", "BA", "OBP", "SLG", "OPS"]
    for col in stat_columns:
        if col not in df.columns:
            df[col] = 0
        df[col] = pd.to_numeric(df[col], errors="coerce")

    with st.expander("Stat minimum filters", expanded=False):
        if prefix == "trend":
            st.caption(
                "Trend page filters use the **combined totals across the selected trend window** "
                "(for example, HR >= 100 means 100 HR across all selected lookback seasons). "
                "Rate-stat filters use the rate calculated from that same selected window."
            )
        count_tab, rate_tab = st.tabs(["Counting stats", "Rate stats"])
        mins = {}
        with count_tab:
            cols = st.columns(4)
            count_filter_cols = [c for c in stat_columns if c not in RATE_STATS]
            for i, stat in enumerate(count_filter_cols):
                with cols[i % 4]:
                    label = f"Min total {stat} (window)" if prefix == "trend" else f"Min {stat}"
                    mins[stat] = st.number_input(
                        label,
                        min_value=0,
                        value=0,
                        step=1,
                        key=f"{prefix}_{stat}_min",
                        on_change=on_change,
                        help=(
                            f"Minimum {stat} combined across selected lookback years."
                            if prefix == "trend"
                            else None
                        ),
                    )
        with rate_tab:
            cols = st.columns(4)
            for i, stat in enumerate([c for c in stat_columns if c in RATE_STATS]):
                with cols[i % 4]:
                    label = f"Min window {stat}" if prefix == "trend" else f"Min {stat}"
                    mins[stat] = st.number_input(
                        label,
                        min_value=0.0,
                        value=0.0,
                        step=0.001,
                        format="%.3f",
                        key=f"{prefix}_{stat}_min",
                        on_change=on_change,
                        help=(
                            f"Minimum {stat} based on the selected trend-window data."
                            if prefix == "trend"
                            else None
                        ),
                    )

    mask = pd.Series(True, index=df.index)
    for stat, min_val in mins.items():
        if min_val:
            mask &= df[stat].fillna(-np.inf) >= min_val
    return df.loc[mask].copy()

def color_trend(val):
    try:
        if pd.isna(val):
            return ""
        num = pd.to_numeric(str(val).replace(",", ""), errors="coerce")
        if pd.isna(num):
            return ""

        # Stronger/darker colors for highly significant values.
        if num >= 1.96:
            return "color: darkgreen; font-weight: 900;"
        if num > 0:
            return "color: green; font-weight: bold;"

        if num <= -1.96:
            return "color: darkred; font-weight: 900;"
        if num < 0:
            return "color: red; font-weight: bold;"

        return "color: gray;"
    except Exception:
        return ""




def color_p_value(val):
    """Use darker colors for highly significant p-values."""
    try:
        if pd.isna(val):
            return ""

        num = pd.to_numeric(str(val).replace(",", ""), errors="coerce")
        if pd.isna(num):
            return ""

        # Extremely significant
        if num < 0.01:
            return "color: darkgreen; font-weight: 900;"

        # Statistically significant
        if num < 0.05:
            return "color: green; font-weight: bold;"

        # Weak/non-significant
        if num > 0.10:
            return "color: darkred; font-weight: bold;"

        return "color: #cc5500; font-weight: bold;"
    except Exception:
        return ""


def style_significance_row(row):
    """Synchronize Difference, Test Statistic, and p-value colors using p-value as the master signal."""
    styles = pd.Series("", index=row.index)
    try:
        p = pd.to_numeric(row.get("p-value", np.nan), errors="coerce")
        diff = pd.to_numeric(row.get("Difference", np.nan), errors="coerce")
    except Exception:
        return styles

    target_cols = [c for c in ["Difference", "Test Statistic", "p-value"] if c in row.index]
    if pd.isna(p) or pd.isna(diff):
        return styles

    if p < 0.01:
        color = "darkgreen" if diff > 0 else "darkred"
        weight = "900"
    elif p < 0.05:
        color = "green" if diff > 0 else "red"
        weight = "bold"
    else:
        # Not statistically significant at the selected alpha level.
        # Keep it neutral so it doesn't look like a real win/loss.
        color = "gray"
        weight = "normal"

    for c in target_cols:
        styles[c] = f"color: {color}; font-weight: {weight};"
    return styles

def color_positive_green(val):
    """Display positive/valuable scores in green."""
    try:
        if pd.isna(val):
            return ""
        num = pd.to_numeric(str(val).replace(",", ""), errors="coerce")
        if pd.isna(num):
            return ""
        if num > 0:
            return "color: green; font-weight: bold;"
        return "color: gray;"
    except Exception:
        return ""


def _extract_numeric_from_arrow(value):
    """Convert values like '▲ 4.2' or '▼ -0.0310' back to numeric for styling."""
    try:
        if pd.isna(value):
            return np.nan
        if isinstance(value, str):
            value = value.replace("▲", "").replace("▼", "").strip()
        return float(value)
    except Exception:
        return np.nan


def trend_heatmap_style(val):
    """Heat-map style for Trend Table: green = improving, red = declining."""
    v = _extract_numeric_from_arrow(val)
    if pd.isna(v):
        return ""
    if v >= 5:
        return "background-color:#006400; color:white; font-weight:bold;"
    if v > 0:
        return "background-color:#c6efce; color:#006100;"
    if v <= -5:
        return "background-color:#8b0000; color:white; font-weight:bold;"
    if v < 0:
        return "background-color:#ffc7ce; color:#9c0006;"
    return ""


def trend_heatmap_style_dynamic(val, col_name):
    """Use tighter thresholds for rate stats like BA/OBP/SLG/OPS."""
    v = _extract_numeric_from_arrow(val)
    if pd.isna(v):
        return ""
    rate_cols = {"BA Δ", "OBP Δ", "SLG Δ", "OPS Δ"}
    if col_name in rate_cols:
        strong = 0.030
    else:
        strong = 5.0
    if v >= strong:
        return "background-color:#006400; color:white; font-weight:bold;"
    if v > 0:
        return "background-color:#c6efce; color:#006100;"
    if v <= -strong:
        return "background-color:#8b0000; color:white; font-weight:bold;"
    if v < 0:
        return "background-color:#ffc7ce; color:#9c0006;"
    return ""


def format_trend_arrow_value(x, is_rate=False):
    """Format a per-season slope (Δ) with arrow — always 2 decimal places."""
    x = pd.to_numeric(x, errors="coerce")
    if pd.isna(x):
        return ""
    arrow = "▲" if x > 0 else ("▼" if x < 0 else "")
    return f"{arrow} {x:.2f}".strip()


def format_fantasy_table(df):
    """Fantasy/Draft display formatting. Ranks and Fantasy Edge are integers; score/rate fields are clean."""
    try:
        from draft_score_display import prepare_draft_scores_for_display

        df = prepare_draft_scores_for_display(df)
    except ImportError:
        df = df.copy()
    if df is None or getattr(df, "empty", True):
        return df if df is not None else pd.DataFrame()
    df = df.copy()
    rank_cols = [
        "Market Rank", "Model Rank", "Current Rank", "FantasyPros Rank", "ADP Rank",
        "Recommendation Rank", "Draft Fit Rank", "Roster Fit Rank", "Draft Rank", "RK", "BEST", "WORST",
    ]
    score_cols = [
        "Player Grade", "Pick Score", "Roster Fit Score", "Relative Draft Grade",
        "Average Player Grade", "Total Player Grade",
        "Recommendation Score", "Sleeper Score", "Bust Risk Score",
        "Player Value Component", "Market Edge Component", "Roster Need Component",
        "Scarcity Component", "Category Fit Component", "Availability Urgency Component",
        "Risk Component", "ML Projection Score", "Blended Projection Score",
    ]
    edge_cols = ["Fantasy Edge"]
    rate_cols = ["BA", "OBP", "SLG", "OPS", "Projected BA", "Projected OBP", "Projected SLG", "Projected OPS"]
    count_cols = ["R", "H", "2B", "3B", "HR", "RBI", "SB", "BB", "Projected G", "Projected PA", "Projected AB", "Projected R", "Projected H", "Projected 2B", "Projected 3B", "Projected HR", "Projected RBI", "Projected SB", "Projected BB"]
    one_decimal_cols = ["ADP", "Expert Std Dev", "Age", "Availability Probability", "Position Need Bonus", "Category Need Bonus", "Risk Penalty"]
    for col in rank_cols + edge_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce").round(0).astype("Int64")
    for col in score_cols:
        if col in df.columns:
            if col == "Player Grade":
                df[col] = pd.to_numeric(df[col], errors="coerce").round(1)
            else:
                df[col] = pd.to_numeric(df[col], errors="coerce").apply(format_trimmed_2dp)
    for col in rate_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce").round(4)
    for col in count_cols + one_decimal_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce").round(1)
    return df

def classify_trend(row):
    ops_trend = pd.to_numeric(row.get("OPS_trend", np.nan), errors="coerce")
    hr_trend = pd.to_numeric(row.get("HR_trend", np.nan), errors="coerce")
    if pd.isna(ops_trend): return "insufficient"
    if ops_trend >= 0.03 or (pd.notna(hr_trend) and hr_trend >= 3): return "breakout"
    if ops_trend <= -0.03 or (pd.notna(hr_trend) and hr_trend <= -3): return "decline"
    return "stable"

def describe_valuation_index(index):
    index = pd.to_numeric(index, errors="coerce")
    if pd.isna(index): return "not enough data to classify the valuation score"
    if index >= 0.90: return "an elite valuation score"
    if index >= 0.75: return "a very strong valuation score"
    if index >= 0.50: return "a solid middle-tier valuation score"
    if index >= 0.25: return "a low valuation score"
    return "a very low valuation score"

def make_trend_insight_summary(row):
    player = row.get("fullName", "This player")
    ops_trend = pd.to_numeric(row.get("OPS_trend", np.nan), errors="coerce")
    hr_trend = pd.to_numeric(row.get("HR_trend", np.nan), errors="coerce")
    rbi_trend = pd.to_numeric(row.get("RBI_trend", np.nan), errors="coerce")
    sb_trend = pd.to_numeric(row.get("SB_trend", np.nan), errors="coerce")
    xbh_trend = pd.to_numeric(row.get("XBH_noHR_trend", np.nan), errors="coerce")
    trend_type = classify_trend(row)
    label = "a breakout candidate" if trend_type == "breakout" else ("a decline risk" if trend_type == "decline" else "a stable profile")

    trend_bits = []
    if pd.notna(ops_trend):
        trend_bits.append(f"OPS trend {fmt_rate_3(ops_trend)}/yr")
    if pd.notna(hr_trend):
        trend_bits.append(f"HR trend {fmt_int(hr_trend)}/yr")
    if pd.notna(xbh_trend):
        trend_bits.append(f"2B+3B trend {fmt_int(xbh_trend)}/yr")
    if pd.notna(rbi_trend):
        trend_bits.append(f"RBI trend {fmt_int(rbi_trend)}/yr")
    if pd.notna(sb_trend):
        trend_bits.append(f"SB trend {fmt_int(sb_trend)}/yr")
    trend_sentence = ", ".join(trend_bits) + "." if trend_bits else "Trend slopes unavailable."

    proj_bits = []
    rate_proj = [
        ("OPS", "proj_OPS"),
        ("AVG", "proj_BA"),
        ("OBP", "proj_OBP"),
        ("SLG", "proj_SLG"),
    ]
    for stat_label, col in rate_proj:
        val = pd.to_numeric(row.get(col, np.nan), errors="coerce")
        if pd.notna(val):
            proj_bits.append(f"{stat_label} {val:.3f}")
    count_proj = [
        ("HR", "proj_HR"),
        ("RBI", "proj_RBI"),
        ("SB", "proj_SB"),
        ("doubles", "proj_2B"),
        ("triples", "proj_3B"),
    ]
    for stat_label, col in count_proj:
        val = pd.to_numeric(row.get(col, np.nan), errors="coerce")
        if pd.notna(val):
            proj_bits.append(f"{int(round(val))} {stat_label}")
    war_val = pd.to_numeric(row.get("proj_WAR", np.nan), errors="coerce")
    if pd.notna(war_val):
        proj_bits.append(f"WAR {war_val:.1f}")
    if not any(
        pd.notna(pd.to_numeric(row.get(c, np.nan), errors="coerce"))
        for c in ("proj_2B", "proj_3B")
    ):
        xbh_val = pd.to_numeric(row.get("proj_XBH", np.nan), errors="coerce")
        if pd.notna(xbh_val):
            proj_bits.append(f"{int(round(xbh_val))} doubles/triples")
    if proj_bits:
        proj_sentence = "Next year projection: " + ", ".join(proj_bits) + "."
    else:
        proj_sentence = "Next year projection unavailable."

    return f"{player} looks like {label}. {trend_sentence} {proj_sentence}"

def make_valuation_summary(row):
    player = row.get("fullName", "This player")
    trend_score = pd.to_numeric(row.get("Trend_Score", np.nan), errors="coerce")
    perf_score = pd.to_numeric(row.get("Perf_Score", np.nan), errors="coerce")
    valuation_score = pd.to_numeric(row.get("Valuation_Score", np.nan), errors="coerce")
    proj_ops = pd.to_numeric(row.get("proj_OPS", np.nan), errors="coerce")
    proj_hr = pd.to_numeric(row.get("proj_HR", np.nan), errors="coerce")
    proj_xbh = pd.to_numeric(row.get("proj_XBH", np.nan), errors="coerce")
    proj_rbi = pd.to_numeric(row.get("proj_RBI", np.nan), errors="coerce")
    proj_sb = pd.to_numeric(row.get("proj_SB", np.nan), errors="coerce")
    try:
        from draft_score_display import fmt_valuation_score

        valuation_display = fmt_valuation_score(valuation_score) or "N/A"
    except ImportError:
        valuation_display = fmt_rate_4(valuation_score)
    valuation_description = describe_valuation_index(valuation_score)
    return (
        f"**{player}** — Valuation Score **{valuation_display}** ({valuation_description}). "
        f"Current production score **{fmt_count_1(perf_score)}**, trend score **{fmt_count_1(trend_score)}** "
        f"(positive trend = improving). If recent form continues, trend-line estimate: "
        f"{fmt_rate_4(proj_ops)} OPS, {fmt_count_1(proj_hr)} HR, {fmt_count_1(proj_rbi)} RBI, {fmt_count_1(proj_sb)} SB."
    )

