def _guide_html_line(text: str) -> str:
    """Escape guide copy for HTML; allow trusted <strong>…</strong> from PAGE_GUIDES extras."""
    raw = str(text or "").strip()
    if not raw:
        return ""
    if re.search(r"</?strong>", raw, flags=re.I):
        return raw
    return html.escape(raw)


def render_page_guide(page_key):
    """Short plain-English intro for the active page (no formula changes)."""
    g = PAGE_GUIDES.get(page_key)
    if not g:
        return
    if pp.is_screenshot_mode(st):
        pp.render_executive_summary(
            st,
            g.get("purpose", ""),
            g.get("when", ""),
            g.get("outputs", ""),
        )
        return
    extra_items = "".join(
        f"<li>{_guide_html_line(x)}</li>" for x in (g.get("extra") or []) if str(x or "").strip()
    )
    st.markdown(
        f"""
        <div class="page-guide">
            <div class="page-guide-title">Quick guide</div>
            <ul>
                <li><strong>What it does:</strong> {_guide_html_line(g.get("purpose", ""))}</li>
                <li><strong>When to use it:</strong> {_guide_html_line(g.get("when", ""))}</li>
                <li><strong>Main outputs:</strong> {_guide_html_line(g.get("outputs", ""))}</li>
                {extra_items}
            </ul>
        </div>
        """,
        unsafe_allow_html=True,
    )


def top_bar_chart(df, name_col, value_col, title, top_n=10):
    if df.empty or value_col not in df.columns or name_col not in df.columns:
        return
    show_chart = st.checkbox(
        f"Show {title}",
        value=pp.chart_default_visible(st),
        key=f"bar_chart_{hashlib.md5(str(title).encode('utf-8')).hexdigest()[:10]}",
        help="Charts are rendered on demand so table-first page loads stay fast.",
    )
    if not show_chart:
        st.caption("Optional chart skipped for faster page load.")
        return
    chart_df = df[[name_col, value_col]].copy()
    chart_df[value_col] = pd.to_numeric(chart_df[value_col], errors="coerce")
    chart_df = chart_df.dropna(subset=[value_col]).sort_values(value_col, ascending=False).head(top_n)
    if chart_df.empty:
        return
    try:
        from player_photos import render_top_n_leaderboard_bar_chart

        people_df = st.session_state.get("people_df")
        if not isinstance(people_df, pd.DataFrame):
            people_df = None
        render_top_n_leaderboard_bar_chart(
            st,
            chart_df,
            name_col,
            value_col,
            title,
            top_n=top_n,
            people_df=people_df,
            use_api=False,
        )
        return
    except ImportError:
        pass
    fig, ax = plt.subplots(figsize=(10, 5))
    ax.barh(chart_df[name_col], chart_df[value_col])
    ax.set_title(title)
    ax.set_xlabel(value_col)
    ax.invert_yaxis()
    try:
        st.pyplot(fig, clear_figure=True)
    except TypeError:
        st.pyplot(fig)
    plt.close(fig)

def format_display_table(df, count_cols=None, rate_cols=None, score_cols=None, count_decimals=0, rate_decimals=3):
    """Return a plain DataFrame for maximum Streamlit Cloud stability.
    Formatting is handled by rounding numeric columns instead of pandas Styler.

    count_decimals / rate_decimals let the Trend page keep change values readable:
    counting-stat changes use 1 decimal, while OPS/BA/OBP/SLG changes use 4 decimals.
    """
    df = df.copy()
    count_cols = count_cols or []
    rate_cols = rate_cols or []
    score_cols = score_cols or []
    for col in count_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce").round(count_decimals)
    for col in rate_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce").round(rate_decimals)
    for col in score_cols:
        if col in df.columns:
            if col in ("Trend Score", "Current Score"):
                df[col] = pd.to_numeric(df[col], errors="coerce").round(2)
            elif col == "Valuation Score":
                try:
                    from draft_score_display import fmt_valuation_score

                    df[col] = pd.to_numeric(df[col], errors="coerce").apply(
                        lambda v: float(fmt_valuation_score(v)) if pd.notna(v) and fmt_valuation_score(v) else np.nan
                    )
                except ImportError:
                    df[col] = pd.to_numeric(df[col], errors="coerce") * 100.0
                df[col] = pd.to_numeric(df[col], errors="coerce").round(2)
            else:
                df[col] = pd.to_numeric(df[col], errors="coerce").round(1)
    return df





MAX_TABLE_DISPLAY_ROWS = 250

@st.cache_data(show_spinner=False)
def _df_to_csv_bytes(df):
    return df.to_csv(index=False).encode("utf-8")

def render_output_table(df, *, key, file_name, display_rows=MAX_TABLE_DISPLAY_ROWS, style_cols=None):
    """Render a table quickly and add a CSV export button that opens cleanly in Excel."""
    from table_display_format import filter_styler_format_map

    table_df = df.copy()
    export_df = table_df
    if _is_team_projected_totals_table_key(key):
        export_df = format_team_projected_totals_table(df.copy(), for_export=True)
        table_df = format_team_projected_totals_table(table_df, for_export=False)
    elif str(key).startswith("draft_lab"):
        table_df = format_draft_lab_table(table_df, for_export=False)
        export_df = format_draft_lab_table(df.copy(), for_export=True)
    if len(table_df) > display_rows:
        st.caption(f"Showing first {display_rows:,} rows. Export downloads all {len(table_df):,} rows.")
        display_df = table_df.head(display_rows)
    else:
        display_df = table_df

    style_cols = [c for c in (style_cols or []) if c in display_df.columns]
    # Avoid heavy styling on large tables. Styling was slowing Trend/Valuation pages and re-expanding decimals.
    if style_cols and display_df.size <= 2500:
        if str(key).startswith("draft_lab"):
            fmt = _draft_lab_styler_format(display_df)
        else:
            fmt = {}
        for col in display_df.columns:
            if str(key).startswith("draft_lab"):
                continue
            if col in TREND_SLOPE_COLS:
                fmt[col] = "{:.2f}"
            elif col == "R-squared":
                fmt[col] = "{:.4f}"
            elif col in TREND_RATE_COLS or col in ALL_TREND_DELTA_COLS or col in ["OPS Δ", "BA Δ", "OBP Δ", "SLG Δ", "HR Δ", "2B+3B Δ", "RBI Δ", "SB Δ"]:
                fmt[col] = "{:.2f}"
            elif col in TREND_COUNT_COLS or col in ["R Δ", "H Δ", "2B Δ", "3B Δ", "BB Δ"]:
                fmt[col] = "{:.2f}"
            elif col in RATE_STATS or col in ["BA", "OBP", "SLG", "OPS"]:
                fmt[col] = "{:.3f}"
            elif col in ["Trend Score", "Current Score", "Performance Score", "Score"]:
                fmt[col] = "{:.1f}"
            elif col == "Valuation Score":
                fmt[col] = "{:.4f}"
            elif col in ("Roster Fit Score", "Draft Fit Score"):
                fmt[col] = "{:.2f}"
            elif col in ("Player Grade", "Pick Score", "Decision Score", "Relative Draft Grade"):
                fmt[col] = "{:.2f}"
            elif col == "Fantasy Edge":
                fmt[col] = "{:.0f}"

        fmt = filter_styler_format_map(display_df, fmt)
        styled_df = display_df.style.format(fmt) if fmt else display_df.style

        red_green_cols = [c for c in style_cols if c in display_df.columns and c != "Roster Fit Score" and c != "Draft Fit Score"]
        green_cols = [c for c in style_cols if c in display_df.columns and c in ("Roster Fit Score", "Draft Fit Score")]

        if red_green_cols:
            styled_df = styled_df.map(color_trend, subset=red_green_cols)
        if green_cols:
            styled_df = styled_df.map(color_positive_green, subset=green_cols)

        # Synchronize Difference, Test Statistic, and p-value colors using p-value as the master signal.
        # This prevents cases where the p-value looks significant but the test statistic/difference use a weaker shade.
        if "p-value" in display_df.columns:
            try:
                styled_df = styled_df.apply(style_significance_row, axis=1)
            except Exception:
                styled_df = styled_df.map(color_p_value, subset=["p-value"])

        # Make long explanation/reason columns readable instead of truncated.
        try:
            st.dataframe(
                styled_df,
                width="stretch",
                hide_index=True,
                row_height=42,
                column_config={
                    "Reason": st.column_config.TextColumn(
                        "Reason",
                        width="large"
                    ),
                    "Interpretation": st.column_config.TextColumn(
                        "Interpretation",
                        width="large"
                    )
                }
            )
        except Exception:
            st.dataframe(styled_df, width="stretch", hide_index=True)
    else:
        st.dataframe(display_df, width="stretch", hide_index=True)

    st.download_button(
        "Export CSV for Excel",
        data=_df_to_csv_bytes(export_df if str(key).startswith("draft_lab") else table_df),
        file_name=file_name,
        mime="text/csv",
        width="content",
    )


def _numeric_plot_columns(df):
    """Return useful numeric columns for chart axes.

    The chart can use internal fields such as Age/Games, but it intentionally
    hides backend IDs and raw birth-date fields from the dropdowns.
    """
    blocked = {"birthday", "birthmonth", "birthyear", "birth day", "birth month", "birth year"}
    preferred = [
        "Age", "G", "AB", "R", "H", "2B", "3B", "HR", "RBI", "SB", "BB",
        "BA", "OBP", "SLG", "OPS", "Current Score", "Valuation Score", "Score",
        "Debut Age", "Final Age", "Average Age"
    ]
    cols = []
    for c in preferred:
        if c in df.columns and c not in cols:
            vals = pd.to_numeric(df[c], errors="coerce")
            if vals.notna().sum() > 0:
                cols.append(c)
    for c in df.columns:
        c_key = str(c).replace("_", " ").lower().strip()
        if c not in cols and c_key not in blocked:
            vals = pd.to_numeric(df[c], errors="coerce")
            if vals.notna().sum() > 0 and not str(c).lower().endswith("id"):
                cols.append(c)
    return cols

def _categorical_plot_columns(df, *, include_hof: bool = True):
    """Color-by options should stay consistent across Historical and Career scatterplots."""
    try:
        from hall_of_fame_data import HOF_SCATTER_COLOR_COL, hof_scatter_color_available
    except ImportError:
        HOF_SCATTER_COLOR_COL = "Hall of Fame"
        hof_scatter_color_available = lambda _df: False  # type: ignore[assignment]

    options = []
    for col in ["Primary Position", "Bats", "Team", "League"]:
        if col in df.columns:
            options.append(col)
    if include_hof and hof_scatter_color_available(df) and HOF_SCATTER_COLOR_COL not in options:
        options.append(HOF_SCATTER_COLOR_COL)
    return options


def _ensure_hof_scatter_columns(plot_df, hof_ids=None):
    """Attach HOF flag + categorical color column for scatterplots."""
    try:
        from hall_of_fame_data import ensure_hof_scatter_columns
    except ImportError:
        return plot_df
    ids = hof_ids if isinstance(hof_ids, frozenset) else globals().get("HOF_PLAYER_IDS")
    if not isinstance(ids, frozenset):
        ids = None
    return ensure_hof_scatter_columns(plot_df, ids)


