def live_draft_build_board_df(room):
    if not room.get("draft_board"):
        return pd.DataFrame()
    df = pd.DataFrame(room["draft_board"])
    rename = {
        "fullName": "Player",
        "Team": "MLB Team",
        "Fantasy Team": "Draft Team",
        "Pick Verdict": "Pick Verdict",
    }
    for old, new in rename.items():
        if old in df.columns and new not in df.columns:
            df = df.rename(columns={old: new})
    show = [
        "Round", "Pick", "Draft Team", "Player", "Primary Position", "MLB Team",
        "Expected Fantasy Value", "Model Rank", "Market Rank", "Fantasy Edge", "Pick Verdict",
    ]
    return df[[c for c in show if c in df.columns]]


def live_draft_recommendations(room, top_n=8, team=None, session=None):
    slot = live_draft_current_slot(room)
    if slot is None:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), pd.DataFrame()
    available = live_draft_get_available(room)
    if available.empty:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), pd.DataFrame()
    target_team = str(team or slot.get("Team") or "").strip()
    if not target_team:
        target_team = str(slot["Team"])
    roster_df = pd.DataFrame(room["rosters"].get(target_team, []))
    cfg = dict(room.get("config", {}))
    try:
        from live_draft_roster_slots import normalize_draft_slot_config

        cfg = normalize_draft_slot_config(cfg)
    except ImportError:
        pass
    cfg["current_pick"] = int(slot.get("Pick", 1))
    cfg["next_user_pick"] = live_draft_next_pick_for_team(room, target_team)
    cfg["num_teams"] = int(cfg.get("num_teams", len(room.get("teams", [])) or 12))
    target_counts = _live_draft_target_counts(cfg)
    fantasy_format = str(cfg.get("fantasy_format") or "5x5 Roto")
    try:
        from live_draft_safe_mode import is_draft_truly_complete

        draft_complete = bool(is_draft_truly_complete(room))
    except ImportError:
        draft_complete = str(room.get("status") or "").strip() == "complete"
    try:
        from draft_needs import infer_draft_team_needs

        need_pos, cat_needs = infer_draft_team_needs(
            roster_df,
            available,
            config=cfg,
            fantasy_format=fantasy_format,
            draft_complete=draft_complete,
        )
        cfg["needed_positions"] = need_pos
        cfg["category_needs"] = cat_needs
    except ImportError:
        pass
    try:
        from contextlib import nullcontext

        from page_perf_phases import session_perf_phase

        score_ctx = (
            session_perf_phase(session, "live_draft_score_available")
            if isinstance(session, dict)
            else nullcontext()
        )
    except ImportError:
        from contextlib import nullcontext

        score_ctx = nullcontext()
    with score_ctx:
        balanced, gaps = _live_draft_score_available(available, roster_df, "balanced recommendation", target_counts, config=cfg, room=room)
    top_recommended = balanced.head(top_n)
    best_available = balanced.sort_values(["Decision Score", "Expected Fantasy Value"], ascending=[False, False]).head(top_n)
    positional = balanced[balanced["Primary Position"].isin(gaps)].sort_values(
        ["Positional Fit", "Draft Fit Score"], ascending=[False, False]
    ).head(top_n) if gaps else pd.DataFrame()
    sleepers = balanced.sort_values(["Sleeper Score", "Draft Fit Score"], ascending=[False, False]).head(top_n)
    return top_recommended, best_available, positional, sleepers


def cached_live_draft_recommendations(session, room, top_n=8, team=None):
    """Reuse recommendation tables within the same pick when the board has not changed."""
    from live_draft_ui_cache import REC_CACHE_KEY, live_draft_ui_cache_key

    cache_key = live_draft_ui_cache_key(session, room, top_n=top_n, team=team)
    entry = session.get(REC_CACHE_KEY)
    if isinstance(entry, dict) and entry.get("key") == cache_key:
        try:
            from live_draft_perf import PHASE_RECOMMENDATIONS, record_cache_action

            record_cache_action(
                session,
                "recommendations",
                phase=PHASE_RECOMMENDATIONS,
                hit=True,
            )
        except ImportError:
            try:
                from page_perf_phases import record_cache_event

                record_cache_event(session, "live_draft_recommendations", hit=True)
            except ImportError:
                pass
        return entry["top_rec"], entry["best_avail"], entry["pos_fit"], entry["value_sleep"]
    t0 = __import__("time").perf_counter()
    try:
        from page_perf_phases import record_cache_event, session_perf_phase

        record_cache_event(session, "live_draft_recommendations", hit=False)
        with session_perf_phase(session, "live_draft_recommendations"):
            top_rec, best_avail, pos_fit, value_sleep = live_draft_recommendations(
                room, top_n=top_n, team=team, session=session
            )
    except ImportError:
        top_rec, best_avail, pos_fit, value_sleep = live_draft_recommendations(
            room, top_n=top_n, team=team, session=session
        )
    try:
        from live_draft_perf import PHASE_RECOMMENDATIONS, record_cache_action

        record_cache_action(
            session,
            "recommendations",
            phase=PHASE_RECOMMENDATIONS,
            hit=False,
            elapsed_sec=__import__("time").perf_counter() - t0,
        )
    except ImportError:
        pass
    session[REC_CACHE_KEY] = {
        "key": cache_key,
        "top_rec": top_rec,
        "best_avail": best_avail,
        "pos_fit": pos_fit,
        "value_sleep": value_sleep,
    }
    return top_rec, best_avail, pos_fit, value_sleep


def live_draft_rosters_df(room):
    rows = []
    for team, players in (room.get("rosters") or {}).items():
        for p in players:
            row = dict(p)
            row["Fantasy Team"] = team
            rows.append(row)
    if not rows:
        return pd.DataFrame()
    df = pd.DataFrame(rows)
    return df.rename(columns={"fullName": "Player", "Team": "MLB Team"})


def live_draft_team_totals(room):
    rosters = live_draft_rosters_df(room)
    if rosters.empty:
        return pd.DataFrame()
    rows = []
    for team, g in rosters.groupby("Fantasy Team"):
        rows.append({
            "Fantasy Team": team,
            "Players": len(g),
            "Total Projected Fantasy Value": safe_numeric_series(g, "Expected Fantasy Value", 0).sum(),
            "Projected HR": safe_numeric_series(g, "proj_HR", 0).sum(),
            "Projected RBI": safe_numeric_series(g, "proj_RBI", 0).sum(),
            "Projected R": safe_numeric_series(g, "proj_R", 0).sum(),
            "Projected SB": safe_numeric_series(g, "proj_SB", 0).sum(),
            "Projected AVG": _weighted_rate(g, "proj_BA"),
            "Projected OPS": _weighted_rate(g, "proj_OPS"),
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out["Projected Team Rank"] = out["Total Projected Fantasy Value"].rank(ascending=False, method="min")
        out = out.sort_values("Projected Team Rank")
    return out


def live_draft_export_frames(room):
    config = room.get("config", {})
    config_rows = pd.DataFrame([{
        "League Name": config.get("league_name", ""),
        "Teams": len(config.get("teams", [])),
        "Picks Per Team": config.get("picks_per_team", ""),
        "Draft Type": config.get("draft_type", "snake"),
        "Scoring Type": config.get("scoring_type", ""),
        "Timer Seconds": config.get("timer_seconds", ""),
        "Auto Pick Rule": config.get("auto_pick_rule", ""),
        "Draft Room ID": room.get("draft_room_id", ""),
        "Status": room.get("status", ""),
    }])
    slot_cfg = pd.DataFrame([config.get("slots", {})])
    available = live_draft_get_available(room)
    avail_show = available.copy()
    if "fullName" in avail_show.columns:
        avail_show = avail_show.rename(columns={"fullName": "Player"})
    totals_df = live_draft_team_totals(room)
    return {
        "draft_configuration": config_rows,
        "roster_settings": slot_cfg,
        "draft_board": live_draft_build_board_df(room),
        "team_rosters": live_draft_rosters_df(room),
        "available_players": avail_show,
        "team_projected_totals": (
            format_team_projected_totals_table(totals_df, for_export=True) if not totals_df.empty else totals_df
        ),
    }


def live_draft_to_lab_draft_df(room):
    """Convert a completed live draft into Draft Simulation Test Mode analysis shape."""
    try:
        from draft_lab_handoff import live_draft_to_lab_draft_df as _handoff_df

        return _handoff_df(room if isinstance(room, dict) else {})
    except ImportError:
        pass
    if not room.get("draft_board"):
        return pd.DataFrame()
    df = pd.DataFrame(room["draft_board"])
    if "Fantasy Team" not in df.columns and "Draft Team" in df.columns:
        df["Fantasy Team"] = df["Draft Team"]
    if "fullName" not in df.columns and "Player" in df.columns:
        df["fullName"] = df["Player"]
    try:
        from draft_lab_analysis import apply_pick_time_snapshots

        df = apply_pick_time_snapshots(df)
    except ImportError:
        pass
    if "Decision Score" not in df.columns:
        df["Decision Score"] = np.nan
    return df


def _live_draft_team_accent(team: str) -> str:
    import hashlib

    digest = hashlib.md5(str(team or "team").encode("utf-8")).hexdigest()
    return f"#{digest[:6]}"


