def _render_live_draft_on_clock_banner(slot, remaining, next_pick=None):
    team = slot.get("Team", "—")
    rnd = slot.get("Round", "—")
    pick_no = slot.get("Pick", "—")
    next_txt = f'<div class="ld-next-pick">Your next pick: #{next_pick}</div>' if next_pick else ""
    accent = _live_draft_team_accent(team)
    st.markdown(
        f"""
        <div class="live-draft-on-clock" style="border-left: 8px solid {accent};">
            <div class="ld-title">On the clock</div>
            <div class="ld-team-name">{team}</div>
            <div class="ld-pick-pills">
                <span class="ld-pill">Round {rnd}</span>
                <span class="ld-pill">Pick {pick_no}</span>
            </div>
            {next_txt}
            <div class="ld-meta">
                <span class="ld-clock-label">Time remaining</span>
                <span class="live-draft-timer">{remaining}s</span>
            </div>
        </div>
        """,
        unsafe_allow_html=True,
    )


def _render_live_draft_rec_cards(rec_df, max_cards=6):
    if rec_df is None or rec_df.empty:
        st.caption("No recommendations available.")
        return
    for _, r in rec_df.head(max_cards).iterrows():
        name = r.get("fullName", "Player")
        pos = r.get("Primary Position", "")
        efv = pd.to_numeric(r.get("Expected Fantasy Value", np.nan), errors="coerce")
        edge = pd.to_numeric(r.get("Fantasy Edge", np.nan), errors="coerce")
        surv = pd.to_numeric(r.get("Survival Probability", np.nan), errors="coerce")
        surv_lbl = str(r.get("Survival Label", ""))
        surv_cls = "surv-high" if pd.notna(surv) and surv >= 0.55 else ("surv-mid" if pd.notna(surv) and surv >= 0.30 else "surv-low")
        surv_pct = f"{surv * 100:.0f}% at next pick" if pd.notna(surv) else ""
        st.markdown(
            f"""
            <div class="live-rec-card">
                <div class="name">{name}</div>
                <div class="pos">{pos} · Player Grade {fmt_player_grade_display(efv)} · Edge {fmt_int(edge)}</div>
                <div class="{surv_cls}">{surv_pct} — {surv_lbl}</div>
            </div>
            """,
            unsafe_allow_html=True,
        )


def live_draft_push_analysis_to_session(room):
    lab_draft = live_draft_to_lab_draft_df(room)
    if is_dataframe_empty(lab_draft):
        return False
    try:
        from draft_lab_handoff import push_completed_live_draft_to_lab, resolve_lab_yearly_df

        return bool(
            push_completed_live_draft_to_lab(
                st.session_state,
                room,
                yearly_df=resolve_lab_yearly_df(st.session_state, yearly_df),
            )
        )
    except ImportError:
        pass
    handoff_meta = {}
    try:
        from draft_lab_handoff import apply_live_draft_handoff_to_session

        handoff_meta = apply_live_draft_handoff_to_session(st.session_state, room)
    except ImportError:
        pass
    pool = room.get("pool", pd.DataFrame())
    config = dict(room.get("config") or {})
    try:
        from draft_lab_analysis import enrich_lab_draft_metrics

        lab_draft = enrich_lab_draft_metrics(lab_draft, pool, config)
    except ImportError:
        pass
    analysis_ctx = {
        "config": config,
        "teams": list(room.get("teams") or []),
        "pool": pool,
        "handoff": handoff_meta,
    }
    try:
        team_summary, strengths, pick_analysis, gaps, actual_summary = analyze_draft_lab_results(
            lab_draft, yearly_df, context=analysis_ctx
        )
        trades = suggest_draft_lab_trades(lab_draft, team_summary, max_suggestions=12)
    except Exception as exc:
        import logging

        logging.getLogger(__name__).warning("live_draft_push_analysis_to_session failed: %s", exc)
        try:
            from baseball_draft_activity import log_draft_analysis_attempted

            log_draft_analysis_attempted(room, session=st.session_state, error=str(exc))
        except Exception:
            pass
        return False
    try:
        from draft_lab_analysis import draft_lab_roster_team_options

        st.session_state["_draft_lab_team_names"] = draft_lab_roster_team_options(list(room.get("teams") or []))
    except ImportError:
        pass
    st.session_state["draft_lab_results"] = {
        "pool": pool,
        "draft": lab_draft,
        "team_summary": team_summary,
        "strengths": strengths,
        "pick_analysis": pick_analysis,
        "gaps": gaps,
        "actual_summary": actual_summary,
        "trades": trades,
        "source": "Live Draft Room",
        "handoff": handoff_meta,
        "analysis_context": analysis_ctx,
    }
    try:
        from baseball_draft_activity import log_draft_analysis_created

        log_draft_analysis_created(room, session=st.session_state, lab_state=st.session_state.get("draft_lab_results"))
    except Exception:
        pass
    try:
        from draft_lab_state import persist_draft_lab_results

        persist_draft_lab_results(st.session_state, st, reason="draft_lab_live_analysis_complete")
    except ImportError:
        pass
    return True


def _persist_live_draft_room(room, *, reason: str, rerun: bool = True) -> None:
    """Write canonical live draft state, sync to draft_room_table, force-save."""
    import time

    from live_draft_state import commit_live_draft_room

    _no_rerun = reason in ("start_draft",)
    if _no_rerun:
        rerun = False
    try:
        from live_draft_start_progress import defer_cloud_autosave_during_start, is_live_draft_start_in_flight, mark_start_step

        if reason == "start_draft" or is_live_draft_start_in_flight(st.session_state):
            defer_cloud_autosave_during_start(st.session_state)
            mark_start_step(st.session_state, "persist_begin", shared_write_start_ts=time.time())
    except ImportError:
        mark_start_step = None  # type: ignore[assignment]

    shared_ok = True
    shared_err = ""
    try:
        from draft_room_context import commit_shared_room_state, is_multiplayer_draft_active

        if is_multiplayer_draft_active(st.session_state):
            ok, msg, _ = commit_shared_room_state(st.session_state, room)
            shared_ok = bool(ok)
            shared_err = str(msg or "")
            if not ok and msg:
                st.warning(msg)
    except ImportError:
        pass
    except Exception as exc:
        shared_ok = False
        shared_err = str(exc)
        st.warning(f"Shared room sync failed: {exc}")

    try:
        if mark_start_step:
            mark_start_step(
                st.session_state,
                "shared_write_done",
                shared_write_end_ts=time.time(),
                shared_write_ok=shared_ok,
                shared_write_error=shared_err or None,
            )
    except Exception:
        pass

    commit_live_draft_room(st, st.session_state, room, reason=reason)
    try:
        from draft_room_state import sync_live_draft_room_to_canonical_board

        sync_live_draft_room_to_canonical_board(st.session_state, room)
    except Exception:
        pass
    try:
        from live_draft_start_progress import mark_start_step

        mark_start_step(
            st.session_state,
            "persist_complete",
            timer_deadline_set=bool(isinstance(room, dict) and room.get("timer_deadline")),
        )
    except ImportError:
        pass
    if rerun:
        st.rerun()


def player_on_fantasy_team(player_name, fantasy_team):
    """Return True if player_name is already on fantasy_team in Draft Room."""
    if not fantasy_team:
        return False
    table = _canonical_draft_board_df()
    if table.empty or "Team" not in table.columns or "Player" not in table.columns:
        return False
    team_rows = table[table["Team"].astype(str) == str(fantasy_team)]
    return str(player_name).strip() in team_rows["Player"].dropna().astype(str).str.strip().tolist()


def _player_display_name(selected_player, label_map) -> str:
    """Best display string for confirmations."""
    sp = str(selected_player or "").strip()
    if not sp:
        return ""
    lbl = resolve_fullname_to_clean_label(sp, label_map)
    if lbl:
        return fullname_base_from_label(lbl)
    return fullname_base_from_label(sp) or sp


def is_active_current_player(player, source_df=None) -> bool:
    """Streamlit wrapper: default eligibility source is the loaded yearly table."""
    df = source_df
    if df is None or getattr(df, "empty", True):
        try:
            df = yearly_df
        except NameError:
            df = pd.DataFrame()
    return plr_act.is_active_current_player(player, df)


def _render_trade_acquire_flow_ui(*, key_prefix: str) -> None:
    """Inline picker for multi-draft Trade / Acquire flows."""
    flow = st.session_state.get(TRADE_FLOW_SESSION_KEY)
    if not isinstance(flow, dict) or flow.get("key_prefix") != key_prefix:
        return

    player = str(flow.get("player") or "").strip()
    step = str(flow.get("step") or "").strip()
    if not player or not step:
        return

    st.markdown("##### Trade / Acquire")
    st.caption(f"Resolving roster context for **{player}**.")

    if step == "choose_mode":
        choice = st.radio(
            "Do you want to trade this player away or acquire this player?",
            ["Trade away", "Acquire"],
            key=f"{key_prefix}_trade_flow_mode",
        )
        if st.button("Continue", key=f"{key_prefix}_trade_flow_mode_continue"):
            mode = TRADE_ACTION_TRADE_AWAY if choice == "Trade away" else TRADE_ACTION_ACQUIRE
            msg = complete_trade_acquire_flow(st.session_state, mode=mode)
            if msg:
                st.session_state[wf_sb.SESSION_SIDEBAR_FLASH] = msg
                try:
                    from baseball_persistent_state import force_save_baseball_state

                    force_save_baseball_state(st, reason="trade_acquire_handoff")
                except Exception:
                    pass
            st.rerun()
        return

    candidates = list(flow.get("candidates") or [])
    if not candidates:
        return

    labels = [format_roster_context_label(ctx) for ctx in candidates]
    context_ids = [str(ctx.get("context_id") or "") for ctx in candidates]
    selected_label = st.selectbox(
        "Which draft context should we use?",
        labels,
        key=f"{key_prefix}_trade_flow_context",
    )
    selected_idx = labels.index(selected_label) if selected_label in labels else 0
    if st.button("Apply Trade / Acquire", key=f"{key_prefix}_trade_flow_apply"):
        msg = complete_trade_acquire_flow(
            st.session_state,
            mode=str(flow.get("mode") or TRADE_ACTION_ACQUIRE),
            context_id=context_ids[selected_idx],
        )
        if msg:
            st.session_state[wf_sb.SESSION_SIDEBAR_FLASH] = msg
            try:
                from baseball_persistent_state import force_save_baseball_state

                force_save_baseball_state(st, reason="trade_acquire_handoff")
            except Exception:
                pass
        st.rerun()


def _on_trade_acquire_flow_click(*, player_raw: str, key_prefix: str):
    display = fullname_base_from_label(str(player_raw or "").strip()) or str(player_raw or "").strip()
    if not is_active_current_player(display):
        st.session_state[wf_sb.SESSION_SIDEBAR_FLASH] = (
            f"{display} is historical/inactive and cannot be added to a current trade workflow."
        )
        st.rerun()
        return
    msg = start_trade_acquire_flow(
        st.session_state,
        player_name=display,
        key_prefix=key_prefix,
    )
    if msg:
        st.session_state[wf_sb.SESSION_SIDEBAR_FLASH] = msg
        try:
            from baseball_persistent_state import force_save_baseball_state

            force_save_baseball_state(st, reason="trade_acquire_handoff")
        except Exception:
            pass
    st.rerun()


def _schedule_player_action_page_nav(target_page: str) -> None:
    """Same navigation path as sidebar, but skip restoring stale page snapshot."""
    tgt = get_sidebar_page_value(target_page)
    st.session_state["_skip_page_restore_for"] = tgt
    st.session_state["_navigate_to_page"] = tgt


def dispatch_player_action(selected_player, action, team_name, user_draft_team, label_map):
    """Run one player action. Returns (message, navigate_to_page_or_none)."""
    sp = str(selected_player or "").strip()
    teams = get_draft_room_team_options()
    if not sp:
        return "Pick a player first.", None

    display = _player_display_name(sp, label_map) or sp
    record_workflow_recent_player(display)
    active_current = is_active_current_player(sp)

    if action == "Draft player to next pick":
        if not active_current:
            return f"{display} is historical/inactive and cannot be drafted into a current simulation.", None
        from draft_actions import can_draft_player, draft_player

        allowed, reason = can_draft_player(st.session_state, sp)
        if not allowed:
            return reason, None
        if not _player_draft_action_available():
            return "Open Draft Room Simulator first to set up teams.", None
        result = draft_player(st.session_state, sp, source="draft_room", st_obj=st)
        return str(result.get("message") or result.get("error") or "Could not draft."), None

    if action == "Queue player":
        if not active_current:
            return f"{display} is historical/inactive and cannot be added to the Draft Queue.", None
        q = st.session_state.get("draft_queue", [])
        if not isinstance(q, list):
            q = []
        if display in q or sp in q:
            return f"{display} is already in your Draft Queue.", None
        msg = add_player_to_queue(sp)
        if "Queued" in msg:
            return f"Added {display} to Draft Queue.", None
        return msg, None

    if action == "Send to Comparison Tool":
        if append_compare_player_ordered(sp, label_map):
            pp = st.session_state.get("pending_compare_players")
            if isinstance(pp, list) and len(pp) >= 2:
                record_workflow_comparison_pair(pp[0], pp[1])
            add_transferred_players_to_tracked_players(
                [display],
                st.session_state.get("active_page"),
                "Comparison Tool",
                transfer_mode="single",
            )
            return f"Added {display} to Comparison Tool.", "Comparison Tool"
        return f"Could not add {display} to Comparison — name not found in the database.", None

    if action == "Send to Trend Page":
        ok, msg = register_players_sent_to_trend_page(sp, label_map)
        if ok:
            add_transferred_players_to_tracked_players(
                [display],
                st.session_state.get("active_page"),
                "Trend Value",
                transfer_mode="single",
            )
            return msg, "Trend Value"
        return msg, None

    if action == "Add to Watchlist":
        if not active_current:
            return f"{display} is historical/inactive and cannot be added to the Watchlist.", None
        from draft_state import add_player_to_watchlist

        st.session_state["pending_draft_assistant_player"] = display
        focus, added = add_player_to_watchlist(st.session_state, display)
        if not added:
            return f"{display} is already on your Watchlist.", None
        try:
            from baseball_persistent_state import force_save_baseball_state

            force_save_baseball_state(st, reason="draft_edit")
        except Exception:
            pass
        return f"Added {display} to Watchlist.", None

    if action in ("Add as trade target to acquire", "Add as player to trade away", "Trade / Acquire"):
        if not active_current:
            return f"{display} is historical/inactive and cannot be added to a current trade workflow.", None
        msg = start_trade_acquire_flow(
            st.session_state,
            player_name=display,
            key_prefix=f"dispatch|{display}",
        )
        if msg:
            return msg, None
        return "", None

    if action == "Simulate drafting this player":
        if not active_current:
            return f"{display} is historical/inactive and cannot be drafted into a current simulation.", None
        if not teams:
            return _NO_DRAFT_CONTEXT_MSG, None
        sim_table, msg = simulate_drafting_player(sp, team_name)
        st.session_state["simulated_draft_room_table"] = sim_table
        return msg, None

    return f"Unknown action: {action}", None


def execute_player_action_once(selected_player, action, team_name, user_draft_team, label_map_compare):
    """Apply one action for one player. Returns a single-line result message."""
    msg, nav = dispatch_player_action(
        selected_player, action, team_name, user_draft_team, label_map_compare
    )
    if nav:
        _schedule_player_action_page_nav(nav)
        st.rerun()
    return msg


def _on_player_action_click(
    action: str,
    player_raw: str,
    team_name=None,
    user_draft_team=None,
):
    """Button callback: update action state only (never button widget keys)."""
    label_map = get_clean_player_label_map_yearly(yearly_df)
    msg, nav = dispatch_player_action(player_raw, action, team_name, user_draft_team, label_map)
    st.session_state[wf_sb.SESSION_SIDEBAR_FLASH] = msg
    if nav:
        _schedule_player_action_page_nav(nav)
    st.rerun()


def _render_player_action_button_row(
    player_raw: str,
    *,
    key_prefix: str,
    label_map,
    team_name=None,
    user_draft_team=None,
    show_queue=True,
    show_comparison=True,
    show_trend=True,
    show_watchlist=True,
    show_draft=False,
    show_trade_acquire=False,
    can_draft=False,
):
    """One-click player actions with stable button keys and shared dispatch."""
    act_suffix = _qa_key_suffix(f"{key_prefix}|{player_raw}")
    kwargs_base = {
        "player_raw": player_raw,
        "team_name": team_name,
        "user_draft_team": user_draft_team,
    }

    on_comparison_page = normalize_page_key(st.session_state.get("active_page") or "") == "Comparison Tool"

    primary = []
    if show_queue:
        primary.append(("Add to Queue", "Queue player", "add_draft_queue"))
    if show_comparison and not on_comparison_page:
        primary.append((page_option_label("Comparison Tool"), "Send to Comparison Tool", "send_comparison"))
    if show_trend:
        primary.append((page_option_label("Trend Value"), "Send to Trend Page", "send_trends"))

    if primary:
        cols = st.columns(len(primary))
        for col, (label, action, slug) in zip(cols, primary):
            with col:
                st.button(
                    label,
                    key=f"plr_act_{act_suffix}_{slug}_button",
                    use_container_width=True,
                    on_click=_on_player_action_click,
                    kwargs={**kwargs_base, "action": action},
                )

    secondary = []
    if show_watchlist:
        secondary.append(("Add to Watchlist", "Add to Watchlist", "add_watchlist"))
    if show_trade_acquire:
        secondary.append(("Trade / Acquire", "Trade / Acquire", "trade_acquire_flow"))
    if show_draft and can_draft:
        secondary.append(("Draft this player", "Draft player to next pick", "draft_player"))

    if secondary:
        cols2 = st.columns(len(secondary))
        for col, (label, action, slug) in zip(cols2, secondary):
            with col:
                if action == "Trade / Acquire":
                    st.button(
                        label,
                        key=f"plr_act_{act_suffix}_{slug}_button",
                        use_container_width=True,
                        on_click=_on_trade_acquire_flow_click,
                        kwargs={"player_raw": player_raw, "key_prefix": key_prefix},
                    )
                else:
                    st.button(
                        label,
                        key=f"plr_act_{act_suffix}_{slug}_button",
                        use_container_width=True,
                        on_click=_on_player_action_click,
                        kwargs={**kwargs_base, "action": action},
                    )


def player_action_menu(
    player_options,
    key,
    default_team=None,
    source_label="this table",
    user_draft_team=None,
    projection_lookup_df=None,
    projection_lookup_name_col="fullName",
    help_text=None,
):
    """Delegate to the same page-only player action UI as compact_player_action_center."""
    return compact_player_action_center(
        player_options,
        key,
        default_team=default_team,
        label="Player actions",
        user_draft_team=user_draft_team,
        projection_lookup_df=projection_lookup_df,
        projection_lookup_name_col=projection_lookup_name_col,
        help_text=help_text,
    )


def compact_player_action_center(
    player_options,
    key,
    default_team=None,
    label="Player Action Center",
    user_draft_team=None,
    projection_lookup_df=None,
    projection_lookup_name_col="fullName",
    help_text=None,
):
    """Primary player workflow: one popover with per-action buttons (no duplicate menus).

    Replaces the legacy multiselect + action dropdown + Run Action control. Trade
    routing still follows roster (inside the popover). Batch multi-select is gone;
    run an action per player inside the popover for the same outcomes.
    """
    ctx = [str(p).strip() for p in list(player_options or []) if str(p).strip()]
    ctx = list(dict.fromkeys(ctx))

    if not ctx:
        st.info("No players in this section for actions.")
        return None

    st.caption(
        "Open Player Actions to **Add to Watchlist**, **Add to Draft Queue**, **Send to Comparison**, "
        "**Send to Trend**, **Simulate Draft Pick**, draft, trade, or view a projection breakdown."
    )
    player_quick_actions_popover(
        ctx,
        key=key,
        user_draft_team=user_draft_team,
        default_team=default_team,
        projection_lookup_df=projection_lookup_df,
        projection_lookup_name_col=projection_lookup_name_col,
        label=label or "Player actions",
        help_text=help_text
        or "Pick a player, then choose an action.",
    )
    sim_result = st.session_state.get(f"{key}_draft_simulation_result")
    if isinstance(sim_result, dict):
        st.markdown("##### Simulate Draft Pick")
        render_draft_simulation_result(sim_result)
        if st.button("Clear simulation", key=f"{key}_clear_draft_simulation"):
            st.session_state.pop(f"{key}_draft_simulation_result", None)
            st.rerun()

    _maybe_show_projection_breakdown_dialog(f"{key}_projection_breakdown_pending")

    return ctx[0] if ctx else None


def _qa_key_suffix(text):
    h = hashlib.sha256(str(text).encode("utf-8")).hexdigest()[:10]
    return h


def _format_projection_stat(label: str, value) -> str:
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return "n/a"
    if label in ("AVG", "OPS"):
        return fmt_rate_3(value)
    return fmt_int(value)


@st.dialog("Projection breakdown", width="large")
def _render_projection_breakdown_dialog(bundle: dict):
    """Scouting-style projection dashboard (stabilized pipeline when available)."""
    if not isinstance(bundle, dict):
        st.warning("No projection breakdown data.")
        return

    player = bundle.get("player_name", "Player")
    st.markdown(f"### {player}")
    ml_on = bool(bundle.get("ml_blend_enabled", True))
    st.caption(
        f"Projection style: **{bundle.get('projection_style', 'Balanced')}** · "
        f"Lookback: **{bundle.get('window_years', 3)}** years · "
        f"ML blend: **{'on' if ml_on else 'off'}** · "
        f"{bundle.get('fantasy_format', '5x5 Roto')}"
    )

    if bundle.get("stabilized"):
        st.success(
            "Canonical projection breakdown — matches the **Proj:** stat line and Player Grade on player cards "
            "using your active shared settings."
        )
    else:
        st.warning(
            "Could not load a stabilized projection row for this player. "
            "Check the name spelling or try again after Lahman data finishes loading."
        )

    snapshot = bundle.get("snapshot") or {}
    projections = snapshot.get("projections") or {}
    if projections:
        st.markdown("#### Canonical projection (matches player card Proj: line)")
        pcols = st.columns(len(projections))
        for col, (label, val) in zip(pcols, projections.items()):
            with col:
                st.metric(f"Projected {label}", _format_projection_stat(label, val))
    elif bundle.get("lahman_fallback"):
        fb = bundle["lahman_fallback"]
        st.markdown(f"#### Latest Lahman season ({fb.get('year', 'n/a')})")
        st.caption(
            f"HR {fmt_int(fb.get('HR'))} · RBI {fmt_int(fb.get('RBI'))} · R {fmt_int(fb.get('R'))} · "
            f"SB {fmt_int(fb.get('SB'))} · OPS {fmt_rate_3(fb.get('OPS'))}"
        )
    else:
        st.info(
            "No projection row found for this player. Check spelling or try **Draft Assistant** after loading market CSVs."
        )

    conf_lbl = snapshot.get("confidence_label")
    conf_score = snapshot.get("confidence_score")
    warning = snapshot.get("warning") or ""
    if conf_lbl or conf_score is not None or warning:
        st.markdown("#### Confidence & warnings")
        if conf_lbl:
            st.markdown(f"**{conf_lbl}**" + (f" (score `{fmt_rate_4(conf_score)}`)" if conf_score is not None else ""))
        elif conf_score is not None:
            st.markdown(f"Confidence score: **{fmt_rate_4(conf_score)}**")
        if warning:
            st.warning(warning)
        if snapshot.get("star_protected"):
            st.caption("Elite-star protection active — lighter regression and softer ceilings on counting stats.")
        if snapshot.get("very_limited_data"):
            st.caption("Small-sample profile: projections are heavily regressed toward recent averages.")

    pos = snapshot.get("primary_position")
    age = snapshot.get("age")
    if pos or (age is not None and not np.isnan(age)):
        g_txt = fmt_int(snapshot.get("games")) if snapshot.get("games") is not None else "n/a"
        ab_txt = fmt_int(snapshot.get("ab")) if snapshot.get("ab") is not None else "n/a"
        pg = snapshot.get("proj_g")
        pab = snapshot.get("proj_ab")
        vol = snapshot.get("volatility_score")
        st.markdown(
            f"**Profile:** {pos or 'n/a'} · age **{fmt_int(age) if age is not None and not np.isnan(age) else 'n/a'}** · "
            f"recent **G={g_txt}** / **AB={ab_txt}** · "
            f"projected playing time **G≈{fmt_int(pg) if pg is not None and not np.isnan(pg) else 'n/a'}**, "
            f"**AB≈{fmt_int(pab) if pab is not None and not np.isnan(pab) else 'n/a'}**"
            + (f" · volatility `{fmt_rate_4(vol)}`" if vol is not None and not np.isnan(vol) else "")
        )

    mr, mdl, fe = snapshot.get("market_rank"), snapshot.get("model_rank"), snapshot.get("fantasy_edge")
    if any(x is not None and not (isinstance(x, float) and np.isnan(x)) for x in (mr, mdl, fe)):
        st.caption(
            f"Market rank **{fmt_int(mr) if mr is not None and not np.isnan(mr) else 'n/a'}** · "
            f"Model rank **{fmt_int(mdl) if mdl is not None and not np.isnan(mdl) else 'n/a'}** · "
            f"Fantasy edge **{fmt_int(fe) if fe is not None and not np.isnan(fe) else 'n/a'}**"
        )

    efv = snapshot.get("player_grade")
    efv_raw = snapshot.get("efv_raw")
    if efv is None and efv_raw is not None and not (isinstance(efv_raw, float) and np.isnan(efv_raw)):
        try:
            from draft_score_display import fmt_player_grade

            efv = fmt_player_grade(efv_raw)
        except ImportError:
            ev = float(efv_raw)
            efv = ev * 100.0 if 0 < ev <= 1.5 else ev
    if efv is None:
        legacy = snapshot.get("expected_fantasy_value")
        if legacy is not None and not np.isnan(legacy):
            try:
                from draft_score_display import fmt_player_grade

                efv = fmt_player_grade(legacy)
            except ImportError:
                ev = float(legacy)
                efv = ev * 100.0 if 0 < ev <= 1.5 else ev
    rbase = snapshot.get("realistic_base")
    ml_adj = snapshot.get("ml_adjustment")
    if efv is not None and efv != "" and not (isinstance(efv, float) and np.isnan(efv)):
        st.caption(
            f"Player Grade **{efv}**"
            + (f" (base **{fmt_rate_4(rbase)}**)" if rbase is not None and not np.isnan(rbase) else "")
            + (f" · ML adj **{float(ml_adj):+.4f}**" if ml_adj is not None and not np.isnan(ml_adj) else "")
        )

    diagnostic = bundle.get("diagnostic_trend_only") or {}
    if diagnostic and bundle.get("stabilized"):
        differs = False
        for label, val in diagnostic.items():
            canon = projections.get(label)
            if canon is None or (isinstance(canon, float) and np.isnan(canon)):
                continue
            tol = 0.002 if label in ("AVG", "OPS") else 0.5
            if abs(float(val) - float(canon)) > tol:
                differs = True
                break
        if differs:
            st.markdown("#### Trend-only diagnostic projection")
            st.caption(
                "Not the canonical forecast — latest full season plus recent linear slope. "
                "Headline stats above match your player card **Proj:** line."
            )
            dcols = st.columns(len(diagnostic))
            for col, (label, val) in zip(dcols, diagnostic.items()):
                with col:
                    st.metric(f"Trend-only {label}", _format_projection_stat(label, val))

    trend_cards = bundle.get("trend_cards") or []
    if trend_cards:
        st.markdown("#### Recent-season trends")
        grid_cols = st.columns(2)
        for i, card in enumerate(trend_cards):
            with grid_cols[i % 2]:
                color = card.get("color", "#57606a")
                arrow = card.get("arrow", "?")
                dir_lbl = card.get("direction_label", "")
                slope_line = card.get("slope_line") or f"Slope: {card.get('slope_display', 'n/a')}"
                title = card.get("title") or f"{card.get('label', '')} Trend"
                explain = card.get("explain", "")
                st.markdown(
                    f"<div style='border:1px solid #e6e8eb;border-radius:8px;padding:8px 10px;margin-bottom:6px;'>"
                    f"<div style='font-weight:700;font-size:0.95rem;margin-bottom:4px;'>{title}</div>"
                    f"<div style='color:{color};font-weight:600;font-size:0.9rem;'>"
                    f"{arrow} {dir_lbl}</div>"
                    f"<div style='color:#24292f;font-size:0.85rem;margin-top:2px;'>{slope_line}</div>"
                    f"<div style='color:#6e7781;font-size:0.75rem;margin-top:4px;line-height:1.3;'>{explain}</div>"
                    f"</div>",
                    unsafe_allow_html=True,
                )

    seasons_used = bundle.get("trend_seasons_used", 0)
    if seasons_used:
        st.caption(f"Trend cards used **{seasons_used}** recent season(s) with enough playing time (40+ games when available).")

    with st.expander("How these numbers are built", expanded=False):
        for note in bundle.get("method_notes") or []:
            st.markdown(f"- {note}")
        st.markdown(
            "- **Projected stats:** blended from recent production, expected playing time, league averages, "
            "and star-tier protection so one hot year does not blow up the forecast."
        )
        st.markdown(
            "- **Trend arrows:** recent full-season direction (home runs, OPS, speed, etc.), "
            "softened when playing time in the window is thin."
        )
        st.markdown(
            "- **ML Predictions** uses a separate machine-learning page; draft tools and this breakdown "
            "share the draft-lab stabilization layer."
        )
        st.caption(f"Data source: `{bundle.get('data_source', 'unknown')}`")


def _on_simulate_draft_pick_click(
    *,
    state_key: str,
    player_raw: str,
    team_name,
    lookup_df,
    lookup_name_col: str,
):
    """Button callback: store simulation result under a dedicated state key (not the button key)."""
    if not is_active_current_player(player_raw):
        st.session_state[state_key] = {
            "player": str(player_raw).strip(),
            "message": "Historical/inactive players cannot be drafted into current simulations.",
            "no_context": True,
            "table": pd.DataFrame(),
        }
        return
    result = build_draft_simulation_result(
        player_raw,
        team_name,
        lookup_df,
        lookup_name_col,
    )
    st.session_state[state_key] = result


def _on_projection_breakdown_click(
    *,
    dialog_state_key: str,
    player_raw: str,
    projection_lookup_df,
    projection_lookup_name_col: str,
):
    """Button callback: queue projection bundle for the next render (never the button widget key)."""
    if not is_active_current_player(player_raw):
        st.session_state[dialog_state_key] = {
            "player_name": str(player_raw).strip(),
            "requested_player": str(player_raw).strip(),
            "stabilized": False,
            "method_notes": ["Historical/inactive players do not have current projection breakdowns."],
        }
        return
    bundle = assemble_projection_breakdown_bundle(
        player_raw,
        pool_row=None,
        projection_lookup_df=None,
        projection_lookup_name_col=projection_lookup_name_col,
    )
    bundle["requested_player"] = str(player_raw).strip()
    st.session_state[dialog_state_key] = bundle
    record_workflow_recent_player(player_raw)


def _maybe_show_projection_breakdown_dialog(dialog_state_key: str):
    bundle = st.session_state.pop(dialog_state_key, None)
    if not bundle:
        return
    if not isinstance(bundle, dict):
        st.warning("Projection breakdown could not be loaded. Please try again.")
        return
    _render_projection_breakdown_dialog(bundle)


def _player_draft_action_available() -> bool:
    """Canonical board can accept a pick (practice, live sync, or manual tracking)."""
    if get_draft_room_team_options():
        return True
    return bool(str(st.session_state.get("room_your_team") or "").strip())


def _on_active_draft_return_click():
    from draft_room_state import get_active_draft_status

    status = get_active_draft_status(st.session_state)
    st.session_state["_navigate_to_page"] = status.get("return_page") or "Draft Room Simulator"


def player_quick_actions_popover(
    player_options,
    *,
    key,
    user_draft_team=None,
    default_team=None,
    projection_lookup_df=None,
    projection_lookup_name_col="fullName",
    label="Player quick actions",
    help_text="Pick a player, then choose an action.",
):
    """Contextual one-click player actions."""
    ctx = [str(p).strip() for p in list(player_options or []) if str(p).strip()]
    ctx = list(dict.fromkeys(ctx))
    if not ctx:
        return

    label_map = get_clean_player_label_map_yearly(yearly_df)
    teams = get_draft_room_team_options()
    team_for_draft = default_team or user_draft_team or st.session_state.get("room_your_team")
    if teams and team_for_draft not in teams:
        team_for_draft = teams[0]

    with st.popover(label):
        if help_text:
            st.caption(help_text)
        pick = st.selectbox(
            "Player",
            ctx,
            index=0,
            key=f"{key}_qa_player_pick",
        )
        sfx = _qa_key_suffix(f"{key}|{pick}")
        active_current = is_active_current_player(pick)
        already_drafted = pick in _drafted_player_names_from_room()
        try:
            from draft_actions import can_draft_player

            draft_ok, _ = can_draft_player(st.session_state, pick)
        except Exception:
            draft_ok = False
        can_draft = active_current and _player_draft_action_available() and draft_ok
        show_trade_acquire = active_current and player_has_roster_context(st.session_state, pick)
        flow_key_prefix = f"{key}_qa_{sfx}"

        _render_player_action_button_row(
            pick,
            key_prefix=flow_key_prefix,
            label_map=label_map,
            team_name=team_for_draft,
            user_draft_team=user_draft_team,
            show_queue=active_current and not already_drafted,
            show_comparison=True,
            show_trend=True,
            show_watchlist=active_current,
            show_draft=active_current,
            show_trade_acquire=show_trade_acquire,
            can_draft=can_draft,
        )
        if not active_current:
            st.caption("Current fantasy actions are hidden for historical/inactive players. Compare, Trends, and historical analytics remain available.")
        elif already_drafted:
            st.caption("Draft queue is hidden because this player is already drafted.")
        elif active_current and not show_trade_acquire:
            st.caption("Trade / Acquire is hidden because this player is not on an active or saved team roster.")

        _render_trade_acquire_flow_ui(key_prefix=flow_key_prefix)

        sim_lookup_df = (
            projection_lookup_df
            if projection_lookup_df is not None and not getattr(projection_lookup_df, "empty", True)
            else default_draft_simulation_lookup()
        )
        sim_lookup_col = (
            projection_lookup_name_col
            if projection_lookup_df is not None and not getattr(projection_lookup_df, "empty", True)
            else "fullName"
        )
        sim_state_key = f"{key}_draft_simulation_result"
        proj_dialog_key = f"{key}_projection_breakdown_pending"

        extra = st.columns(2)
        with extra[0]:
            if active_current and has_draft_room_context():
                st.button(
                    "Simulate Draft Pick",
                    key=f"plr_act_{sfx}_simulate_draft_button",
                    on_click=_on_simulate_draft_pick_click,
                    kwargs={
                        "state_key": sim_state_key,
                        "player_raw": pick,
                        "team_name": team_for_draft,
                        "lookup_df": sim_lookup_df,
                        "lookup_name_col": sim_lookup_col,
                    },
                )
        with extra[1]:
            if active_current:
                st.button(
                    "Projection breakdown",
                    key=f"plr_act_{sfx}_projection_breakdown_button",
                    on_click=_on_projection_breakdown_click,
                    kwargs={
                        "dialog_state_key": proj_dialog_key,
                        "player_raw": pick,
                        "projection_lookup_df": projection_lookup_df,
                        "projection_lookup_name_col": projection_lookup_name_col,
                    },
                )


def render_contextual_player_actions(
    label,
    player_id,
    *,
    key_prefix,
    source_df,
    team_name=None,
    label_map=None,
    projection_lookup_df=None,
    projection_lookup_name_col="fullName",
):
    """Compact context-aware actions for Comparison and Significance selected players."""
    player_name = fullname_base_from_label(label)
    active_current = is_active_current_player({"playerID": player_id, "fullName": player_name}, source_df=source_df)
    already_drafted = player_name in _drafted_player_names_from_room()
    active_available = active_current and not already_drafted
    show_trade_acquire = active_current and player_has_roster_context(st.session_state, player_name)
    label_map = label_map or get_clean_player_label_map_yearly(source_df)
    try:
        from draft_actions import can_draft_player

        draft_ok, _ = can_draft_player(st.session_state, player_name)
    except Exception:
        draft_ok = False
    act_id = _qa_key_suffix(f"{key_prefix}|{player_name}")
    flow_key_prefix = f"ctx_{act_id}"
    with st.popover(f"Actions: {player_name}"):
        st.caption("Active/current player" if active_current else "Historical/inactive player")
        _render_player_action_button_row(
            label,
            key_prefix=flow_key_prefix,
            label_map=label_map,
            team_name=team_name,
            user_draft_team=team_name,
            show_queue=active_available,
            show_comparison=True,
            show_trend=True,
            show_watchlist=active_current,
            show_draft=active_available and draft_ok,
            show_trade_acquire=show_trade_acquire,
            can_draft=active_available and draft_ok,
        )

        if not active_current:
            st.caption("Watchlist, projection, draft, queue, and trade actions are hidden for historical/inactive players.")
        if already_drafted:
            st.caption("Draft queue is hidden because this player is already drafted.")
        elif active_current and not show_trade_acquire:
            st.caption("Trade / Acquire is hidden because this player is not on an active or saved team roster.")

        _render_trade_acquire_flow_ui(key_prefix=flow_key_prefix)

        ctx_sim_key = f"ctx_{act_id}_draft_simulation_result"
        ctx_proj_key = f"ctx_{act_id}_projection_breakdown_pending"
        ctx_sim_lookup = (
            projection_lookup_df
            if projection_lookup_df is not None and not getattr(projection_lookup_df, "empty", True)
            else default_draft_simulation_lookup()
        )
        ctx_sim_col = (
            projection_lookup_name_col
            if projection_lookup_df is not None and not getattr(projection_lookup_df, "empty", True)
            else "fullName"
        )

        if active_current:
            st.button(
                "Projection breakdown",
                key=f"plr_act_{act_id}_projection_breakdown_button",
                on_click=_on_projection_breakdown_click,
                kwargs={
                    "dialog_state_key": ctx_proj_key,
                    "player_raw": player_name,
                    "projection_lookup_df": projection_lookup_df,
                    "projection_lookup_name_col": projection_lookup_name_col,
                },
            )
            _maybe_show_projection_breakdown_dialog(ctx_proj_key)

        if active_available:
            st.button(
                "Simulate Draft Pick",
                key=f"plr_act_{act_id}_simulate_draft_button",
                on_click=_on_simulate_draft_pick_click,
                kwargs={
                    "state_key": ctx_sim_key,
                    "player_raw": player_name,
                    "team_name": team_name,
                    "lookup_df": ctx_sim_lookup,
                    "lookup_name_col": ctx_sim_col,
                },
            )
            sim_result = st.session_state.get(ctx_sim_key)
            if isinstance(sim_result, dict):
                render_draft_simulation_result(sim_result)


def clickable_player_draft_table(df, player_col="Player", team_name=None, key="clickable_draft_table", title="Clickable Draft Table"):
    """Interactive player table: select one row and draft that player to the next Draft Room pick.

    Uses Streamlit's built-in dataframe row-selection events, so it does not require extra packages.
    """
    if df is None or df.empty:
        st.info(f"{title}: no players available.")
        return None

    table = df.copy()
    if player_col not in table.columns:
        st.warning(f"{title}: missing player column.")
        return None

    st.caption("Click a row in the table below, then press the draft button.")
    event = st.dataframe(
        table,
        use_container_width=True,
        hide_index=True,
        selection_mode="single-row",
        on_select="rerun",
        key=key
    )

    selected_player = None
    try:
        selected_rows = event.selection.rows
        if selected_rows:
            selected_player = str(table.iloc[selected_rows[0]][player_col])
    except Exception:
        selected_player = None

    if selected_player:
        st.success(f"Selected: {selected_player}")
        draft_teams = get_draft_room_team_options()
        if draft_teams:
            if team_name is None:
                default_team = st.session_state.get("room_your_team", draft_teams[0])
                default_idx = draft_teams.index(default_team) if default_team in draft_teams else 0
                team_name = st.selectbox(
                    "Draft Room team",
                    draft_teams,
                    index=default_idx,
                    key=f"{key}_team"
                )
            else:
                st.caption(f"Drafting to: {team_name}")

            from draft_ui import render_draft_button

            if render_draft_button(
                st,
                st.session_state,
                selected_player,
                source="draft_room",
                key_suffix=f"{key}_sel",
                label=f"Draft {selected_player}",
                button_type="primary",
                flash_key="workflow_sidebar_flash",
            ):
                st.rerun()
        else:
            st.info("Open Draft Room Simulator first so the app knows the fantasy teams.")
    return selected_player


def get_draft_room_team_options():
    table = _canonical_draft_board_df()
    if table.empty or "Team" not in table.columns:
        return []
    return sorted(table["Team"].dropna().astype(str).unique().tolist())


def add_player_to_next_draft_room_pick(player_name, team_name=None):
    """Draft player on the user's turn (legacy name — routes through draft_player)."""
    from draft_actions import draft_player

    result = draft_player(st.session_state, player_name, source="draft_room", st_obj=st)
    return str(result.get("message") or result.get("error") or "Could not add player.")


def draft_top_queue_player():
    """Draft #1 queue player (legacy wrapper — routes through draft_player)."""
    q = st.session_state.get("draft_queue") or []
    if not q:
        return "Draft queue is empty."
    from draft_actions import draft_player

    result = draft_player(st.session_state, str(q[0]).strip(), source="queue", st_obj=st)
    return str(result.get("message") or result.get("error") or "Could not draft from queue.")


def draft_queue_player_at_index(idx: int):
    """Draft a specific queue player (legacy wrapper — routes through draft_player)."""
    q = st.session_state.get("draft_queue") or []
    try:
        index = int(idx)
    except (TypeError, ValueError):
        return "Invalid queue index."
    if index < 0 or index >= len(q):
        return "Queue index out of range."
    from draft_actions import draft_player

    result = draft_player(st.session_state, str(q[index]).strip(), source="queue", st_obj=st)
    return str(result.get("message") or result.get("error") or "Could not draft from queue.")


def build_draft_room_table_from_assistant(my_roster, other_rosters, my_team_name="My Team", other_team_name="Other Rosters"):
    rows = []
    pick = 1
    for p in list(my_roster or []):
        if str(p).strip():
            rows.append({"Round": pick, "Pick": pick, "Team": my_team_name, "Player": str(p).strip()})
            pick += 1
    for p in list(other_rosters or []):
        if str(p).strip():
            rows.append({"Round": pick, "Pick": pick, "Team": other_team_name, "Player": str(p).strip()})
            pick += 1
    return pd.DataFrame(rows, columns=["Round", "Pick", "Team", "Player"])


def sync_draft_room_to_assistant_from_table(draft_room_table, my_team_name):
    try:
        from draft_room_state import coerce_board_table

        df = coerce_board_table(draft_room_table)
    except Exception:
        df = draft_room_table if hasattr(draft_room_table, "copy") else pd.DataFrame()
    if df is None or getattr(df, "empty", True):
        return [], []
    df = df.copy()
    if "Player" not in df.columns or "Team" not in df.columns:
        return [], []
    df = df[df["Player"].astype(str).str.strip() != ""].copy()
    my_roster = df[df["Team"].astype(str) == str(my_team_name)]["Player"].dropna().astype(str).tolist()
    other_rosters = df[df["Team"].astype(str) != str(my_team_name)]["Player"].dropna().astype(str).tolist()
    return sorted(list(dict.fromkeys(my_roster))), sorted(list(dict.fromkeys(other_rosters)))


