def record_workflow_recent_player(display_name):
    """MRU list of display names the user acted on (session only)."""
    name = str(display_name).strip()
    if not name:
        return
    lst = st.session_state.get("workflow_recently_viewed", [])
    st.session_state["workflow_recently_viewed"] = wf_sb.merge_mru(lst, name, wf_sb.RECENT_VIEW_CAP)
    try:
        from baseball_persistent_state import force_save_baseball_state

        force_save_baseball_state(st, reason="tracked_players")
    except Exception:
        pass


def _short_workflow_page_name(page: str | None) -> str:
    """Short page names for Tracked Players transfer batch labels."""
    key = normalize_page_key(page) if page else ""
    return {
        "Trend Value": "Trends",
        "Comparison Tool": "Comparison",
        "Valuation": "Valuation",
        "Historical Explorer": "Historical Explorer",
        "Career Totals": "Career Totals",
        "Leaderboards": "Leaderboards",
        "Fantasy Sleepers & Busts": "Sleepers",
    }.get(key, key or "page")


def _transfer_track_batch_label(
    source_page: str | None,
    target_page: str,
    *,
    transfer_mode: str | None = None,
    player_count: int = 0,
) -> str:
    tgt = _short_workflow_page_name(target_page)
    src = _short_workflow_page_name(source_page)
    mode = str(transfer_mode or "").lower()
    if mode == "top_3" and src:
        return f"Top 3 from {src}"
    if src:
        return f"Transferred to {tgt}"
    return f"Transferred to {tgt}"


def add_transferred_players_to_tracked_players(
    players,
    source_page: str | None,
    target_page: str,
    *,
    transfer_mode: str | None = None,
):
    """
    Add successfully transferred players to Tracked Players (sidebar).
    Call only after target-page validation with the final player list.
    """
    names = []
    seen = set()
    for raw in players or []:
        display = fullname_base_from_label(str(raw).strip()) or str(raw).strip()
        if not display or display in seen:
            continue
        seen.add(display)
        names.append(display)
    if not names:
        return

    batch_label = _transfer_track_batch_label(
        source_page,
        target_page,
        transfer_mode=transfer_mode,
        player_count=len(names),
    )
    batches = st.session_state.get(wf_sb.SESSION_TRANSFER_BATCHES, [])
    st.session_state[wf_sb.SESSION_TRANSFER_BATCHES] = wf_sb.append_transfer_batch(
        batches,
        label=batch_label,
        players=names,
        source=source_page,
        target=target_page,
    )

    rv = st.session_state.get("workflow_recently_viewed", [])
    st.session_state["workflow_recently_viewed"] = wf_sb.merge_mru_batch(
        rv, names, wf_sb.RECENT_VIEW_CAP
    )
    if len(names) >= 2:
        record_workflow_comparison_group(names)
    try:
        from baseball_persistent_state import force_save_baseball_state

        force_save_baseball_state(st, reason="tracked_players")
    except Exception:
        pass


def record_workflow_comparison_pair(label_a, label_b):
    """Store ordered A vs B pairs for one-click reload (deduped by unordered pair)."""
    record_workflow_comparison_group([label_a, label_b])


def record_workflow_comparison_group(labels):
    """Store a compact recent comparison/trend group in the sidebar history."""
    names = []
    for label in labels or []:
        name = fullname_base_from_label(label)
        if name and name not in names:
            names.append(name)
    if len(names) < 2:
        return
    pairs = st.session_state.get("workflow_recent_compare_pairs", [])
    if not isinstance(pairs, list):
        pairs = []
    sig = tuple(sorted(names))
    kept = [
        p for p in pairs
        if isinstance(p, (list, tuple))
        and len(p) >= 2
        and tuple(sorted(str(x).strip() for x in p if str(x).strip())) != sig
    ]
    kept.append(names)
    st.session_state["workflow_recent_compare_pairs"] = kept[-wf_sb.RECENT_COMPARE_CAP:]


def _workflow_normalize_draft_queue():
    from draft_state import sync_draft_queue

    sync_draft_queue(st.session_state, st.session_state.get("draft_queue"), reason="normalize_queue")


def _drafted_player_names_from_room():
    """Names already drafted by any team; used only to prune unavailable draft queue items."""
    table = _canonical_draft_board_df()
    if table is None or getattr(table, "empty", True) or "Player" not in table.columns:
        return set()
    return {
        str(x).strip()
        for x in table["Player"].dropna().astype(str).tolist()
        if str(x).strip()
    }


def _auto_remove_drafted_from_queue():
    """Remove drafted players from Draft Queue, but leave Watchlist/Tracked Players untouched."""
    from draft_state import sync_draft_queue

    _workflow_normalize_draft_queue()
    drafted = _drafted_player_names_from_room()
    if not drafted:
        return []
    q = st.session_state.get("draft_queue", []) or []
    kept = [p for p in q if str(p).strip() not in drafted]
    removed = [p for p in q if str(p).strip() in drafted]
    if removed:
        sync_draft_queue(st.session_state, kept, reason="auto_remove_drafted")
        try:
            from baseball_persistent_state import force_save_baseball_state

            force_save_baseball_state(st, reason="draft_edit")
        except Exception:
            pass
    return removed


def _move_queue_item(idx, delta):
    from draft_state import mark_draft_pending_sync, sync_draft_queue

    q = list(st.session_state.get("draft_queue", []) or [])
    new_idx = idx + delta
    if idx < 0 or idx >= len(q) or new_idx < 0 or new_idx >= len(q):
        return
    q[idx], q[new_idx] = q[new_idx], q[idx]
    sync_draft_queue(st.session_state, q, reason="reorder_queue")
    mark_draft_pending_sync(st.session_state)


def _clear_workflow_list(key):
    from draft_state import clear_draft_queue, clear_watchlist

    if key == "draft_queue":
        clear_draft_queue(st.session_state, reason="clear_queue")
    elif key in ("draft_assistant_focus_players", "workflow_favorite_targets"):
        clear_watchlist(st.session_state, reason="clear_watchlist")
    else:
        st.session_state[key] = []
    try:
        from baseball_persistent_state import force_save_baseball_state

        force_save_baseball_state(st, reason="draft_edit")
    except Exception:
        pass


def render_persistent_workflow_sidebar(_yearly_df_local=None):
    """Persistent workflow panel: draft queue, watchlist, and tracked players."""
    try:
        from draft_room_state import render_active_draft_banner

        render_active_draft_banner(st, st.session_state, page_label_fn=page_option_label)
    except Exception:
        pass
    _workflow_normalize_draft_queue()
    removed_drafted = _auto_remove_drafted_from_queue()

    flash = st.session_state.pop("workflow_sidebar_flash", None)
    if flash:
        flash_s = str(flash)
        if flash_s.lower().startswith("skipped") or "could not" in flash_s.lower() or "not found" in flash_s.lower():
            st.sidebar.warning(flash_s)
        else:
            st.sidebar.success(flash_s)
    if removed_drafted:
        st.sidebar.info(
            "Removed drafted player(s) from Draft Queue: "
            + ", ".join(str(x) for x in removed_drafted[:3])
            + (f" +{len(removed_drafted) - 3} more" if len(removed_drafted) > 3 else "")
        )

    try:
        from fantasy_trade_notifications_ui import render_trade_notification_sidebar

        render_trade_notification_sidebar(st, st.session_state)
    except ImportError:
        pass

    dq = st.session_state.get("draft_queue", []) or []
    watch = st.session_state.get("draft_assistant_focus_players", []) or []
    favorites = st.session_state.get("workflow_favorite_targets", []) or []
    if not isinstance(watch, list):
        watch = []
    if not isinstance(favorites, list):
        favorites = []
    watch = list(dict.fromkeys([str(x).strip() for x in favorites + watch if str(x).strip()]))
    rv = st.session_state.get("workflow_recently_viewed", [])
    if not isinstance(rv, list):
        rv = []
    pairs = st.session_state.get("workflow_recent_compare_pairs", [])
    if not isinstance(pairs, list):
        pairs = []
    transfer_batches = st.session_state.get(wf_sb.SESSION_TRANSFER_BATCHES, [])
    if not isinstance(transfer_batches, list):
        transfer_batches = []

    try:
        from draft_actions import draft_action_context
        from draft_ui import (
            render_active_draft_ownership_dev_panel,
            render_draft_button,
            render_draft_queue_panel,
            render_draft_sidebar_status,
        )

        draft_ctx = draft_action_context(st.session_state)
        render_draft_sidebar_status(st, st.session_state)
        render_active_draft_ownership_dev_panel(
            st,
            st.session_state,
            player_name=str(dq[0]).strip() if dq else "",
            developer_mode=developer_mode_enabled(),
        )
    except Exception:
        draft_ctx = {}
        render_draft_button = None

    st.sidebar.divider()
    st.sidebar.markdown("### Draft from lists")
    if draft_ctx.get("active_draft_source"):
        st.sidebar.caption(f"Active draft source: **{draft_ctx['active_draft_source']}**")

    st.sidebar.markdown("**Draft queue**")
    try:
        if render_draft_queue_panel(
            st,
            st.session_state,
            key_prefix="sidebar_queue",
            use_sidebar=True,
            max_rows=12,
            show_subheader=False,
            compact=True,
        ):
            try:
                from baseball_persistent_state import force_save_baseball_state

                force_save_baseball_state(st, reason="draft_edit")
            except Exception:
                pass
            st.rerun()
    except NameError:
        pass
    if st.sidebar.button(
        "Clear Draft Queue",
        key="sidebar_clear_draft_queue",
        disabled=not bool(st.session_state.get("draft_queue")),
    ):
        _clear_workflow_list("draft_queue")
        st.rerun()

    st.sidebar.markdown("**Watchlist**")
    if not watch:
        st.sidebar.caption("Empty — use **Add to Watchlist** from Player Actions.")
    else:
        for idx, pname in enumerate(list(reversed(watch[-12:]))):
            label = str(pname).strip()
            w_name, w_draft = st.sidebar.columns([0.68, 0.32])
            w_name.caption(label[:38] + ("…" if len(label) > 38 else ""))
            if render_draft_button and render_draft_button(
                st,
                st.session_state,
                label,
                source="watchlist",
                key_suffix=f"w_{idx}",
                column=w_draft,
            ):
                st.rerun()
        if len(watch) > 12:
            st.sidebar.caption(f"+{len(watch) - 12} more")
        if st.sidebar.button("Clear Watchlist", key="sidebar_clear_watchlist", disabled=not bool(watch)):
            _clear_workflow_list("draft_assistant_focus_players")
            _clear_workflow_list("workflow_favorite_targets")
            st.rerun()

    st.sidebar.markdown("**Tracked players**")
    if not rv:
        st.sidebar.caption("Recently viewed players appear here after you analyze or compare.")
    else:
        for idx, pname in enumerate(list(reversed(rv[-8:]))):
            label = str(pname).strip()
            t_name, t_draft = st.sidebar.columns([0.68, 0.32])
            t_name.caption("• " + label[:36] + ("…" if len(label) > 36 else ""))
            if render_draft_button and render_draft_button(
                st,
                st.session_state,
                label,
                source="tracked",
                key_suffix=f"t_{idx}",
                column=t_draft,
            ):
                st.rerun()
    if pairs:
        st.sidebar.caption("Recent comparisons")
        for pair in reversed(pairs[-3:]):
            if isinstance(pair, (list, tuple)) and len(pair) >= 2:
                names = [str(x).strip() for x in pair if str(x).strip()]
                st.sidebar.caption("• " + " vs ".join(names)[:50])
    if st.sidebar.button(
        "Clear Tracked Players",
        key="sidebar_clear_tracked_players",
        disabled=not bool(rv or pairs or transfer_batches),
    ):
        _clear_workflow_list("workflow_recently_viewed")
        _clear_workflow_list("workflow_recent_compare_pairs")
        _clear_workflow_list(wf_sb.SESSION_TRANSFER_BATCHES)
        st.rerun()


