def render_developer_mode_sidebar_toggle():
    """Single sidebar switch for all developer-only tools (default OFF)."""
    try:
        from suite_workspace import (
            DEVELOPER_MODE_DIAG_KEY,
            developer_tools_workspace_eligible,
            record_developer_mode_diagnostics,
            sync_developer_mode_widget,
        )

        sync_developer_mode_widget(st.session_state, source="pre_toggle_render")
        if not developer_tools_workspace_eligible(st=st):
            return
    except ImportError:
        pass

    try:
        from suite_sidebar_run import GUARD_DEV_TOGGLE, claim_sidebar_render

        if not claim_sidebar_render(st.session_state, GUARD_DEV_TOGGLE):
            return
    except ImportError:
        pass

    if DEVELOPER_MODE_KEY not in st.session_state:
        st.session_state[DEVELOPER_MODE_KEY] = bool(st.session_state.get("_suite_developer_mode_user"))

    def _on_developer_mode_change() -> None:
        try:
            from suite_workspace import set_developer_mode_user

            set_developer_mode_user(
                st.session_state,
                bool(st.session_state.get(DEVELOPER_MODE_KEY)),
                source="checkbox",
            )
        except ImportError:
            pass

    st.sidebar.checkbox(
        "Developer Mode",
        key=DEVELOPER_MODE_KEY,
        on_change=_on_developer_mode_change,
        help="Show saved filter state, performance timing, scoring validation, and draft score breakdowns.",
    )
    try:
        from suite_workspace import record_developer_mode_diagnostics

        record_developer_mode_diagnostics(st.session_state, source="post_toggle_render")
        if developer_mode_enabled():
            diag = st.session_state.get(DEVELOPER_MODE_DIAG_KEY)
            if isinstance(diag, dict) and (
                diag.get("developer_mode_restored_value") or diag.get("developer_mode_reset_reason")
            ):
                with st.sidebar.expander("Developer mode trace", expanded=False):
                    for label, value in diag.items():
                        st.text(f"{label}: {value}")
    except ImportError:
        pass
    if developer_mode_enabled():
        try:
            from page_perf_diagnostics import render_page_perf_diagnostics

            render_page_perf_diagnostics(st)
        except ImportError:
            pass


def migrate_legacy_widget_keys():
    """One-time copy from old widget keys to new stable names."""
    import copy
    for new_key, old_key in LEGACY_WIDGET_KEY_MIGRATIONS.items():
        if old_key in st.session_state and new_key not in st.session_state:
            st.session_state[new_key] = copy.deepcopy(st.session_state[old_key])
    if "_active_page_selector" in st.session_state and MAIN_SIDEBAR_PAGE_KEY not in st.session_state:
        old_page = normalize_page_key(st.session_state["_active_page_selector"])
        if old_page in _PAGE_OPTION_SET:
            st.session_state[MAIN_SIDEBAR_PAGE_KEY] = old_page


def init_state_once(key, default):
    """Set a session key only the first time — never overwrite user choices."""
    if key not in st.session_state:
        st.session_state[key] = default


def validate_state_option(key, options, default=None):
    """Selectbox/radio: init once; tolerate redeploy enum drift with nearest mapping."""
    opts = list(options)
    if not opts:
        return
    fallback = default if default is not None else opts[0]
    if fallback not in opts:
        fallback = opts[0]
    warn_key = f"_suite_validate_warn::{key}"
    stale_key = f"_suite_stale_option::{key}"
    if key not in st.session_state:
        st.session_state[key] = fallback
        st.session_state.pop(warn_key, None)
        st.session_state.pop(stale_key, None)
        return
    current = st.session_state[key]
    if current in opts:
        st.session_state.pop(warn_key, None)
        return
    stale = current
    mapped = None
    stale_l = str(stale).lower()
    for opt in opts:
        if str(opt).lower() == stale_l:
            mapped = opt
            break
    if mapped is None:
        for opt in opts:
            opt_l = str(opt).lower()
            if stale_l in opt_l or opt_l in stale_l:
                mapped = opt
                break
    if mapped is not None:
        st.session_state[stale_key] = stale
        st.session_state[key] = mapped
        if developer_mode_enabled():
            st.session_state[warn_key] = f"Mapped restored value '{stale}' → '{mapped}'"
        return
    st.session_state[stale_key] = stale
    st.session_state[key] = fallback
    if developer_mode_enabled():
        st.session_state[warn_key] = (
            f"Restored value '{stale}' is not in current options; using '{fallback}'"
        )


def validate_multiselect_options(key, options, default=None):
    """Multiselect: init once; drop invalid selections only (do not reset to full default)."""
    opts = list(options)
    if key not in st.session_state:
        st.session_state[key] = list(default) if default is not None else []
    elif not isinstance(st.session_state.get(key), list):
        st.session_state[key] = list(default) if default is not None else []
    elif st.session_state.get("_transfer_just_applied_to") != st.session_state.get("active_page"):
        st.session_state[key] = [x for x in st.session_state[key] if x in opts]


def validate_slider_range(key, min_value, max_value, default=None):
    """Range slider: init once; clamp stored tuple into bounds."""
    from year_range_state import sanitize_year_range

    min_value = int(min_value)
    max_value = int(max_value)
    if default is None:
        default = (min_value, max_value)
    raw = st.session_state.get(key) if key in st.session_state else None
    sanitized = sanitize_year_range(raw, min_value, max_value, default)
    if sanitized is None:
        st.session_state[key] = (min_value, max_value)
    else:
        st.session_state[key] = sanitized


def validate_number_state(key, default, min_value=None, max_value=None, as_int=True):
    if key not in st.session_state:
        st.session_state[key] = default
    else:
        try:
            val = int(st.session_state[key]) if as_int else float(st.session_state[key])
            if min_value is not None:
                val = max(min_value, val)
            if max_value is not None:
                val = min(max_value, val)
            st.session_state[key] = val
        except (TypeError, ValueError):
            st.session_state[key] = default


def validate_text_state(key, default: str):
    init_state_once(key, default)


# Back-compat aliases used across the app.
def ensure_widget_state(key: str, default):
    init_state_once(key, default)
    return st.session_state[key]


def ensure_multiselect_state(key: str, options, default_selection):
    validate_multiselect_options(key, options, default_selection)
    return st.session_state[key]


def ensure_slider_range(key: str, min_value: int, max_value: int, default_range):
    validate_slider_range(key, min_value, max_value, default_range)
    return st.session_state[key]


def ensure_select_in_options(key: str, options, default_value):
    validate_state_option(key, options, default_value)
    return st.session_state[key]


def ensure_number_state(key: str, default, min_value=None, max_value=None, as_int=True):
    validate_number_state(key, default, min_value, max_value, as_int)
    return st.session_state[key]


def ensure_text_state(key: str, default: str):
    validate_text_state(key, default)
    return st.session_state[key]


def _debug_session_value_repr(val):
    """Arrow-safe string for debug tables (mixed list/scalar session values)."""
    if isinstance(val, (list, tuple, set, dict)):
        return repr(val)
    return val


def render_page_filters_debug(page_name: str):
    """Bottom-of-page debug: confirm filter keys survive sidebar navigation."""
    if pp.is_screenshot_mode(st) or not developer_mode_enabled():
        return
    prefixes = PAGE_STATE_DEBUG_PREFIXES.get(normalize_page_key(page_name), ())
    rows = []
    for k in sorted(st.session_state.keys()):
        if not isinstance(k, str):
            continue
        if any(k.startswith(p) for p in prefixes):
            rows.append({"key": k, "value": _debug_session_value_repr(st.session_state[k])})
    with st.expander("Debug: current saved filters", expanded=False):
        st.caption(f"Page: **{page_name}** — values in `st.session_state` (restored on sidebar return).")
        if rows:
            st.dataframe(pd.DataFrame(rows), width="stretch", hide_index=True)
        else:
            st.caption("No filter keys stored yet for this page.")
    render_global_settings_trace()
    render_settings_persistence_trace(page_name)


def render_settings_persistence_trace(page_name: str):
    """Dev-mode: per-setting persistence trace for the draft/settings pages that revert.

    Shows, for each tracked setting on this page, the value in every storage tier
    (session / canonical / page snapshot / cloud blob / disk blob) plus the recorded
    SAVE and RESTORE lifecycle events — so we can see exactly where a value drops.
    """
    if pp.is_screenshot_mode(st) or not developer_mode_enabled():
        return
    try:
        import settings_persistence_trace as spt
    except ImportError:
        return
    page = normalize_page_key(page_name)
    if not spt.tracked_specs_for_page(page):
        return

    with st.expander("Debug: settings persistence trace (where does it revert?)", expanded=False):
        st.caption(
            "Per setting: value in session vs canonical vs page snapshot vs the durable "
            "cloud/disk blob. If after refresh `session`/`page_snapshot` show defaults but "
            "`cloud_snapshot` is correct → RESTORE drops it. If `cloud_snapshot` is "
            "default/old right after a save → SAVE never persisted it."
        )
        # Auto-load the durable blobs every render (dev-mode only, perf is fine) so the
        # cloud/disk columns are never empty just because nobody clicked a button. A
        # manual refresh button is still offered for re-reading after a save.
        cloud_state: dict = {}
        disk_state: dict = {}
        force_reload = st.button("Reload durable cloud + disk blobs", key=f"_spt_load_{page}")
        cached_cloud = st.session_state.get("_spt_cloud_cache")
        cached_disk = st.session_state.get("_spt_disk_cache")
        if force_reload or cached_cloud is None or cached_disk is None:
            try:
                from suite_cloud_state import load_cloud_full_session

                cloud_state, _ = load_cloud_full_session("baseball")
            except Exception as exc:
                st.caption(f"cloud load failed: {exc}")
            try:
                from suite_user_persistence import load_user_state

                disk_state, _ = load_user_state("baseball")
            except Exception as exc:
                st.caption(f"disk load failed: {exc}")
            st.session_state["_spt_cloud_cache"] = cloud_state
            st.session_state["_spt_disk_cache"] = disk_state
        else:
            cloud_state = cached_cloud
            disk_state = cached_disk

        # ── DECISIVE SIGNAL: does the durable blob actually contain THIS page? ──
        st.caption("**Durable blob contents for this page** (the decisive save/restore signal):")
        st.write({
            "page": page,
            "cloud": spt.durable_pf_summary(cloud_state, page),
            "disk": spt.durable_pf_summary(disk_state, page),
        })

        # Startup / sync status — did the durable cloud blob actually get applied on
        # this load? If apply was skipped, restored values never reach the widgets and
        # they fall back to seeded defaults (the offline build/apply cycle proves the
        # durable cycle itself is correct, so a skip here is the prime suspect).
        st.caption("**Startup / sync status this load:**")
        st.write({
            "workspace_sync_skipped_no_apply": st.session_state.get("_suite_workspace_sync_skipped_no_apply"),
            "cloud_workspace_applied": st.session_state.get("_suite_cloud_workspace_applied"),
            "page_overwrite_source": st.session_state.get("_suite_page_overwrite_source"),
            "last_save_reason": st.session_state.get("_suite_persist_last_save_reason"),
            "last_save_cloud": st.session_state.get("_suite_persist_last_save_cloud"),
            "last_cloud_error": st.session_state.get("_suite_persist_last_cloud_error"),
            "autosave_blocked_after_restore": st.session_state.get("_suite_autosave_blocked_after_restore"),
            "autosave_block_reason": st.session_state.get("_suite_autosave_block_reason"),
            "draft_room_locally_dirty_flag": st.session_state.get("draft_room_state_dirty"),
        })

        rows = spt.build_comparison_rows(
            st.session_state, page, cloud_state=cloud_state, disk_state=disk_state
        )
        if rows:
            st.dataframe(pd.DataFrame(rows), width="stretch", hide_index=True)
        else:
            st.caption("No tracked settings for this page.")

        save_trace = [e for e in spt.get_save_trace(st.session_state) if e.get("active_page") == page]
        if save_trace:
            st.caption("**SAVE events** (newest last) — reason / cloud allowed / what was written:")
            st.json(save_trace[-6:])
        restore_trace = [e for e in spt.get_restore_trace(st.session_state) if e.get("page") == page]
        if restore_trace:
            st.caption("**RESTORE events** (newest last) — blob value vs final session value:")
            st.json(restore_trace[-6:])
        onchange = spt.get_onchange_trace(st.session_state)
        if onchange:
            st.caption("**on_change events** (newest last):")
            st.json(onchange[-8:])


