def open_waiver_wire_from_lineup_slot(slot_label: str = "") -> None:
    """Streamlit on_click — open Waiver Wire with a lineup slot position filter applied."""
    try:
        from draft_archive_ui import FANTASY_WAIVER_PAGE, schedule_fantasy_analysis_navigation
        from fantasy_waiver_wire_ui import WAIVER_POSITION_FILTER_KEY
        from fantasy_weekly_lineup import waiver_filter_for_slot_label
    except ImportError:
        navigate_to_page("Waiver Wire / Add-Drop Center", from_callback=True)
        return
    filt = waiver_filter_for_slot_label(str(slot_label or ""))
    if filt:
        st.session_state[WAIVER_POSITION_FILTER_KEY] = filt
    else:
        st.session_state.pop(WAIVER_POSITION_FILTER_KEY, None)
    if not schedule_fantasy_analysis_navigation(st.session_state, FANTASY_WAIVER_PAGE):
        navigate_to_page(FANTASY_WAIVER_PAGE, from_callback=True)


def navigate_to_page(target_page, transfer_payload=None, *, source_page=None, from_callback=False):
    """
    One-click navigation: queue transfer, schedule page change, rerun.
    Page change is applied in _consume_scheduled_navigation() before the sidebar radio.
    """
    target = get_sidebar_page_value(target_page)
    if target not in _PAGE_OPTION_SET:
        return False
    if transfer_payload is not None:
        set_pending_page_transfer(target, transfer_payload, source_page)
    st.session_state["_navigate_to_page"] = target
    if not from_callback:
        st.rerun()
    return True


def go_to_related_page(target_page, transfer_payload=None, *, source_page=None, navigate_only=False):
    """Backward-compatible alias for navigate_to_page."""
    if navigate_only:
        return navigate_to_page(target_page, transfer_payload=None, source_page=source_page)
    return navigate_to_page(target_page, transfer_payload, source_page=source_page)


def request_sidebar_page(page: str):
    """Navigate via the main sidebar page key (single source of truth)."""
    navigate_to_page(page, transfer_payload=None)


def save_page_state(page_name: str):
    """Persist the current page's widget keys into ``page_filter_state``."""
    store = st.session_state.setdefault("page_filter_state", {})
    pg_state.save_page_state(st.session_state, normalize_page_key(page_name), store)


def _record_settings_onchange(
    page_name: str,
    handler: str,
    reason: str,
    *,
    save_page_state: bool = True,
    force_save: bool = True,
):
    """Dev trace: log that a settings on_change fired and what it triggered."""
    try:
        from settings_persistence_trace import record_onchange

        record_onchange(
            st.session_state,
            page_name,
            handler=handler,
            save_page_state=save_page_state,
            force_save=force_save,
            reason=reason,
        )
    except Exception:
        pass


def restore_page_state(page_name: str) -> bool:
    """Restore a saved snapshot for sidebar return visits (not contextual transfers)."""
    store = st.session_state.get("page_filter_state", {})
    return pg_state.restore_page_state(st.session_state, normalize_page_key(page_name), store)


