def set_pending_page_transfer(target_page: str, transfer_payload=None, source_page=None):
    """Queue contextual transfer (filters / players / draft objects) for the next navigation."""
    target = normalize_page_key(target_page)
    if target not in _PAGE_OPTION_SET:
        return
    payload = pg_xfer.normalize_transfer_payload(transfer_payload)
    st.session_state["_pending_page_transfer"] = {
        "target": target,
        "source": normalize_page_key(source_page) if source_page else None,
        "payload": payload,
        # Legacy readers still expect "filters" at top level.
        "filters": payload,
    }


def _expand_transfer_filter_keys(page: str, keys: dict) -> dict:
    """Map internal transfer keys (lags) onto target-page widget keys."""
    out = dict(keys or {})
    if "_transfer_value_lag" in out:
        lag = out.pop("_transfer_value_lag")
        try:
            max_y = int(st.session_state.get("_lahman_max_year", year_max))
            out["compare_year_range"] = (max_y - int(lag) + 1, max_y)
        except Exception:
            pass
    if "_transfer_trend_lag" in out:
        lag = out.pop("_transfer_trend_lag")
        try:
            max_y = int(st.session_state.get("_lahman_max_year", year_max))
            out["compare_year_range"] = (max_y - int(lag) + 1, max_y)
        except Exception:
            pass
    lag_trend = out.get("trend_lag")
    if lag_trend in (3, 4, 5) and "compare_year_range" not in out and page == "Comparison Tool":
        try:
            max_y = int(st.session_state.get("_lahman_max_year", year_max))
            out["compare_year_range"] = (max_y - int(lag_trend) + 1, max_y)
        except Exception:
            pass
    xfer_pos = out.pop("transfer_position", None)
    if xfer_pos:
        pos = pg_xfer.normalize_fantasy_position_filter(xfer_pos)
        if pos:
            out.update(pg_xfer.fantasy_position_transfer_keys_for_target(page, pos))
    return out


def _apply_transfer_payload_to_page(
    page: str,
    payload: dict,
    *,
    source_page: str | None = None,
) -> bool:
    """Write transfer filters/players onto session_state for the target page."""
    page = normalize_page_key(page)
    payload = pg_xfer.normalize_transfer_payload(payload or {})
    keys = _expand_transfer_filter_keys(page, dict(payload.get("transfer_filters") or {}))
    if keys:
        _apply_transfer_session_keys(page, keys)
    for action in payload.get("actions") or []:
        if action == "push_live_draft_to_lab":
            room = st.session_state.get("live_draft_room")
            if isinstance(room, dict):
                try:
                    from live_draft_safe_mode import is_draft_truly_complete

                    draft_complete = bool(is_draft_truly_complete(room))
                except ImportError:
                    draft_complete = str(room.get("status") or "").strip() == "complete"
                if draft_complete:
                    live_draft_push_analysis_to_session(room)
    _clear_stale_transfer_player_state()
    players = payload.get("transfer_players") or {}
    player_mode = str((players or {}).get("mode", "none")).lower()
    applied_players = []
    if player_mode not in ("", "none"):
        if page == "Comparison Tool":
            applied_players = _apply_transfer_players_to_compare(players)
        elif page == "Trend Value":
            applied_players = _apply_transfer_players_to_trend(players)
        elif page == "Valuation":
            applied_players = _apply_transfer_players_to_valuation(players)
        if applied_players:
            add_transferred_players_to_tracked_players(
                applied_players,
                source_page,
                page,
                transfer_mode=player_mode,
            )
    highlight = payload.get("draft_assistant_highlight")
    if highlight and page == "Draft Assistant Simulator":
        st.session_state["pending_draft_assistant_player"] = str(highlight)
    st.session_state["_transfer_just_applied_to"] = page
    return True


def request_contextual_page(target_page: str, transfer_payload=None, source_page=None):
    """Navigate with transfer payload (one click)."""
    navigate_to_page(target_page, transfer_payload, source_page=source_page)


def _ctx_nav_on_open_tool(nav_target_key: str, nav_payload_key: str, source_page: str, meta_key: str):
    """Button callback: rebuild payload from latest checkbox, then schedule navigation."""
    meta = st.session_state.get(meta_key) or {}
    target = st.session_state.get(nav_target_key) or meta.get("go_target")
    if not target:
        return
    target = get_sidebar_page_value(target)
    builder_id = meta.get("builder_id") or ""
    source = meta.get("source") or source_page
    placement_key = meta.get("placement_key") or ""
    go_target = get_sidebar_page_value(meta.get("go_target") or target)
    base_extra = dict(st.session_state.get(f"ctx_nav_base_extra_{source}_{placement_key}") or {})
    xfer_df = st.session_state.get(f"ctx_nav_xfer_df_{source}_{placement_key}")
    xfer_col = st.session_state.get(f"ctx_nav_xfer_col_{source}_{placement_key}", "fullName")
    if xfer_df is not None:
        base_extra["transfer_results_df"] = xfer_df
        base_extra["results_df"] = xfer_df
        base_extra["transfer_name_col"] = xfer_col
        base_extra["results_player_col"] = xfer_col
    ctx = dict(base_extra)
    show_top3 = bool(meta.get("show_top3_checkbox"))
    if show_top3:
        ctx["send_top_3_players"] = bool(
            st.session_state.get(f"{source}_{go_target}_send_top_3_players", False)
        )
    else:
        ctx["send_top_3_players"] = False
    if target:
        ctx["target_page"] = normalize_page_key(target)
    payload = pg_xfer.build_transfer(st.session_state, builder_id, ctx) if builder_id else None
    navigate_to_page(target, payload, source_page=source_page, from_callback=True)


def _apply_transfer_session_keys(target_page: str, keys: dict):
    """Apply contextual transfer keys only when allowed and valid for the target page."""
    allowed = _PAGE_TRANSFER_ALLOWED_KEYS.get(target_page, frozenset())
    if not allowed:
        return
    clean = pg_xfer.sanitize_session_keys(keys or {}, allowed)
    for key, value in clean.items():
        try:
            st.session_state[key] = value
        except Exception:
            pass


def _clear_stale_transfer_player_state():
    """Remove prior contextual-transfer player queues before applying a new payload."""
    for key in (
        "pending_compare_players",
        "pending_compare_clear_player_b",
        "pending_trend_players",
        "pending_trend_player",
        "trend_multi_queue_fullnames",
        "trend_anchor_fullname",
        "trend_force_single_label",
        "trend_force_multi_labels",
    ):
        st.session_state.pop(key, None)


def _apply_transfer_players_to_compare(players: dict):
    label_map = get_clean_player_label_map_yearly(yearly_df)
    mode = str((players or {}).get("mode", "none")).lower()
    if mode in ("", "none"):
        try:
            from comparison_state import write_canonical_comparison_state

            write_canonical_comparison_state(st.session_state, [], reason="transfer_clear")
        except Exception:
            st.session_state["compare_players"] = []
            st.session_state["compare_players_saved"] = []
        return
    labels = list(players.get("labels") or [])
    if not labels:
        for name in players.get("names") or []:
            lbl = resolve_fullname_to_clean_label(name, label_map)
            if lbl and lbl not in labels:
                labels.append(lbl)
    if not labels:
        return
    try:
        from comparison_state import write_canonical_comparison_state

        write_canonical_comparison_state(st.session_state, labels[:3], reason="transfer_apply")
    except Exception:
        st.session_state["compare_players"] = labels[:3]
        st.session_state["compare_players_saved"] = labels[:3]


def _valid_trend_chart_labels(candidate_labels, label_map, *, lag_years=None, min_seasons=2):
    """Labels that exist in the Trends UI and have enough recent seasons to graph."""
    try:
        lag = int(lag_years if lag_years is not None else st.session_state.get("trend_lag", 3))
    except (TypeError, ValueError):
        lag = 3
    if lag not in (3, 4, 5):
        lag = 3
    max_y = int(st.session_state.get("_lahman_max_year", year_max))
    min_y = max_y - lag + 1
    allowed = set(get_sorted_clean_player_label_keys(yearly_df))
    valid = []
    for raw in candidate_labels:
        lbl = str(raw).strip()
        if not lbl:
            continue
        if lbl not in label_map:
            resolved = resolve_fullname_to_clean_label(lbl, label_map)
            lbl = resolved or lbl
        if not lbl or lbl not in allowed or lbl not in label_map:
            continue
        pid = label_map[lbl]
        sub = yearly_df[
            (yearly_df["playerID"] == pid)
            & (yearly_df["yearID"] >= min_y)
            & (yearly_df["yearID"] <= max_y)
        ]
        if len(sub) < min_seasons:
            continue
        if lbl not in valid:
            valid.append(lbl)
        if len(valid) >= 3:
            break
    return valid


def _apply_transfer_players_to_trend(players: dict):
    label_map = get_clean_player_label_map_yearly(yearly_df)
    mode = str((players or {}).get("mode", "none")).lower()
    st.session_state.pop("trend_chart_transfer_note", None)
    if mode in ("", "none"):
        st.session_state.pop("trend_players_multi", None)
        st.session_state.pop("trend_multi_queue_fullnames", None)
        st.session_state.pop("trend_anchor_fullname", None)
        st.session_state.pop("trend_force_single_label", None)
        st.session_state.pop("trend_force_multi_labels", None)
        return

    candidates = []
    if mode == "compare_selected":
        candidates = [str(x).strip() for x in (players.get("labels") or []) if str(x).strip()]
    else:
        for name in players.get("names") or []:
            candidates.append(str(name).strip())
        for lbl in players.get("labels") or []:
            candidates.append(str(lbl).strip())

    valid = _valid_trend_chart_labels(candidates, label_map)
    if not valid:
        return

    chart_labels = valid[:3]
    st.session_state["trend_players_multi"] = chart_labels
    st.session_state["single_trend_dashboard_player"] = chart_labels[0]
    st.session_state["trend_force_multi_labels"] = chart_labels
    st.session_state["trend_force_single_label"] = chart_labels[0]
    st.session_state["trend_anchor_fullname"] = fullname_base_from_label(chart_labels[0])
    st.session_state["trend_multi_queue_fullnames"] = [
        fullname_base_from_label(lbl) for lbl in chart_labels
    ]
    st.session_state["pending_trend_players"] = [
        fullname_base_from_label(lbl) for lbl in chart_labels
    ]
    st.session_state["pending_trend_player"] = fullname_base_from_label(chart_labels[0])

    if len(candidates) > len(chart_labels) or len(candidates) > 3:
        st.session_state["trend_chart_transfer_note"] = (
            f"Showing first {len(chart_labels)} valid transferred players."
        )


def _apply_transfer_players_to_valuation(players: dict):
    mode = str((players or {}).get("mode", "none")).lower()
    if mode in ("", "none"):
        st.session_state.pop("valuation_selected_player", None)
        return
    names = list(players.get("names") or [])
    seen = set()
    deduped = []
    for n in names:
        n = str(n).strip()
        if n and n not in seen:
            seen.add(n)
            deduped.append(n)
    if deduped:
        st.session_state["valuation_selected_player"] = deduped[0]


def apply_pending_page_transfer(current_page: str):
    """Apply queued contextual transfer when landing on the target page (idempotent)."""
    pending = st.session_state.get("_pending_page_transfer")
    if not pending:
        return False
    target = normalize_page_key(pending.get("target"))
    page = normalize_page_key(current_page)
    if target != page:
        return False
    st.session_state.pop("_pending_page_transfer", None)
    payload = pending.get("payload") or pending.get("filters") or {}
    source = pending.get("source")
    return _apply_transfer_payload_to_page(page, payload, source_page=source)


def _preview_transfer_player_names(ent, base_extra, main_xfer_df, name_col, *, send_top3: bool):
    if not ent:
        return []
    builder = ent.get("builder") or ""
    if builder in getattr(pg_xfer, "_BUILDER_COMPARE_SELECTED_PLAYERS", frozenset()):
        labels = base_extra.get("compare_selected_labels") or st.session_state.get("compare_players") or []
        return [str(x).split(" (")[0].strip() for x in labels if str(x).strip()]
    if send_top3:
        return pg_xfer.top_players_in_display_order(main_xfer_df, player_col=name_col, limit=3)
    return []


def render_contextual_page_nav(
    source_page: str,
    placement_key: str,
    label: str = "Continue analysis in…",
    extra_context=None,
    *,
    results_df=None,
    results_player_col="Player",
    default_rank_stat="OPS",
    transfer_results_df=None,
    transfer_name_col=None,
):
    """
    Contextual navigation: transfers filters/settings; optional top-3 players via checkbox only.
    Sidebar navigation restores each page's saved state and does not use this control.
    """
    source = normalize_page_key(source_page)
    registry = getattr(pg_xfer, "CONTEXTUAL_NAV_REGISTRY", {})
    lookup_source = source
    try:
        from draft_lab_state import DRAFT_LAB_PAGE, DRAFT_LAB_PAGE_LEGACY

        if source == DRAFT_LAB_PAGE:
            lookup_source = DRAFT_LAB_PAGE_LEGACY
    except ImportError:
        pass
    entries = registry.get((lookup_source, placement_key), [])
    if not entries:
        entries = registry.get((source, placement_key), [])
    if not entries:
        return

    main_xfer_df = transfer_results_df if transfer_results_df is not None else results_df
    name_col = transfer_name_col or results_player_col or "fullName"
    rank_stat = default_rank_stat
    has_source_players = pg_xfer.source_has_transferable_players(main_xfer_df, name_col)

    option_labels = ["— Stay on this page —"]
    option_entries = [None]
    for ent in entries:
        tgt = normalize_page_key(ent["target"])
        if tgt not in _PAGE_OPTION_SET or tgt == source:
            continue
        builder = ent.get("builder") or ""
        option_labels.append(
            pg_xfer.contextual_nav_option_label(
                tgt,
                builder,
                target_display=page_option_label(tgt),
                has_source_players=has_source_players,
            )
        )
        option_entries.append(ent)
    if len(option_labels) < 2:
        return

    base_extra = dict(extra_context or {})
    base_extra.setdefault("dataset_max_year", st.session_state.get("_lahman_max_year", year_max))
    if main_xfer_df is not None:
        base_extra["transfer_results_df"] = main_xfer_df
        base_extra["results_df"] = main_xfer_df
    base_extra["transfer_name_col"] = name_col
    base_extra["results_player_col"] = name_col
    base_extra["rank_stat"] = rank_stat
    base_extra["default_rank_stat"] = rank_stat
    st.session_state[f"ctx_nav_base_extra_{source}_{placement_key}"] = {
        k: v
        for k, v in base_extra.items()
        if k not in ("transfer_results_df", "results_df")
    }
    if main_xfer_df is not None:
        st.session_state[f"ctx_nav_xfer_df_{source}_{placement_key}"] = main_xfer_df
        st.session_state[f"ctx_nav_xfer_col_{source}_{placement_key}"] = name_col
    choice_key = f"ctx_choice_{source}_{placement_key}"
    go_key = f"ctx_go_{source}_{placement_key}_btn"
    nav_target_key = f"ctx_nav_target_{source}_{placement_key}"
    nav_payload_key = f"ctx_nav_payload_{source}_{placement_key}"

    with st.container():
        st.markdown('<div class="ctx-transfer-row">', unsafe_allow_html=True)
        choice = st.selectbox(label, option_labels, index=0, key=choice_key)
        sel_idx = option_labels.index(choice) if choice in option_labels else 0
        ent = option_entries[sel_idx]
        target_page = normalize_page_key(ent["target"]) if ent else None
        builder_id = ent.get("builder") or "" if ent else ""

        send_top3 = False
        show_top3_checkbox = bool(
            ent
            and pg_xfer.should_show_top3_checkbox(
                builder_id,
                target_page or "",
                main_xfer_df,
                name_col,
                source_page=source,
            )
        )
        if show_top3_checkbox:
            chk_key = f"{source}_{target_page}_send_top_3_players"
            _top3_label = (
                pg_xfer.top3_checkbox_label(source, builder_id)
                if hasattr(pg_xfer, "top3_checkbox_label")
                else CONTEXTUAL_TOP3_CHECKBOX_LABEL
            )
            send_top3 = st.checkbox(
                _top3_label,
                value=False,
                key=chk_key,
            )

        preview_names = _preview_transfer_player_names(
            ent, base_extra, main_xfer_df, name_col, send_top3=send_top3
        )

        if ent:
            go_target = get_sidebar_page_value(ent["target"])
            st.session_state[nav_target_key] = go_target
            st.session_state[f"ctx_nav_meta_{source}_{placement_key}"] = {
                "source": source,
                "placement_key": placement_key,
                "builder_id": builder_id,
                "go_target": go_target,
                "show_top3_checkbox": show_top3_checkbox,
            }
            st.session_state.pop(nav_payload_key, None)
        else:
            st.session_state.pop(nav_target_key, None)
            st.session_state.pop(nav_payload_key, None)
            st.session_state.pop(f"ctx_nav_meta_{source}_{placement_key}", None)
        if (
            builder_id in getattr(pg_xfer, "_BUILDER_COMPARE_SELECTED_PLAYERS", frozenset())
            and pg_xfer.target_accepts_transferred_players(target_page or "")
        ):
            _cmp_preview = _preview_transfer_player_names(
                ent, base_extra, main_xfer_df, name_col, send_top3=False
            )
            if _cmp_preview:
                st.caption(f"Sending comparison players: {', '.join(_cmp_preview)}")
        elif show_top3_checkbox and send_top3 and preview_names:
            _top3_cap = (
                pg_xfer.top3_transfer_caption(source, preview_names)
                if hasattr(pg_xfer, "top3_transfer_caption")
                else f"Sending top 3 players: {', '.join(preview_names[:3])}"
            )
            if _top3_cap:
                st.caption(_top3_cap)

        st.button(
            "Open selected tool",
            key=go_key,
            use_container_width=True,
            disabled=not bool(ent),
            on_click=_ctx_nav_on_open_tool,
            kwargs={
                "nav_target_key": nav_target_key,
                "nav_payload_key": nav_payload_key,
                "source_page": source,
                "meta_key": f"ctx_nav_meta_{source}_{placement_key}",
            },
        )
        st.markdown("</div>", unsafe_allow_html=True)


