def _prepare_and_show_draft_shared_settings(
    page: str,
    *,
    lookback_key: str | None = None,
    style_key: str | None = None,
    format_key: str | None = None,
) -> None:
    try:
        from shared_draft_context import (
            prepare_shared_draft_context,
            render_draft_shared_settings_diagnostics,
        )
        from live_draft_perf import PHASE_SETUP_SHARED_CONTEXT, live_draft_perf_action

        with live_draft_perf_action(st.session_state, "shared_context", phase=PHASE_SETUP_SHARED_CONTEXT):
            prepare_shared_draft_context(st.session_state, active_page=page, force_mirror=True)
        render_draft_shared_settings_diagnostics(
            st,
            st.session_state,
            active_page=page,
            widget_lookback_key=lookback_key,
            widget_style_key=style_key,
            widget_format_key=format_key,
        )
    except ImportError:
        try:
            from shared_draft_context import (
                prepare_shared_draft_context,
                render_draft_shared_settings_diagnostics,
            )

            prepare_shared_draft_context(st.session_state, active_page=page, force_mirror=True)
            render_draft_shared_settings_diagnostics(
                st,
                st.session_state,
                active_page=page,
                widget_lookback_key=lookback_key,
                widget_style_key=style_key,
                widget_format_key=format_key,
            )
        except ImportError:
            pass


def fantasy_filter_changed():
    try:
        from fantasy_state import mark_fantasy_filter_pending_sync, section_for_page

        section = section_for_page(st.session_state.get("active_page", ""))
        if section:
            mark_fantasy_filter_pending_sync(st.session_state, section)
    except Exception:
        pass
    # Propagate lineup scoring (roto/points) to canonical format.
    try:
        from global_fantasy_settings_state import on_lineup_format_changed

        if "lineup_format" in st.session_state:
            on_lineup_format_changed(st.session_state)
    except Exception:
        pass
    # Propagate any alias format change to the canonical key so all pages see it.
    try:
        from global_fantasy_settings_state import FORMAT_ALIASES, on_alias_format_changed

        for alias_key in FORMAT_ALIASES:
            if alias_key in st.session_state:
                on_alias_format_changed(st.session_state, alias_key)
                break
    except Exception:
        pass
    try:
        from shared_draft_context import on_draft_settings_changed

        on_draft_settings_changed(
            st.session_state,
            source_page="Fantasy Sleepers & Busts",
            lookback_key="fantasy_market_window",
            min_games_key="fantasy_market_min_g",
            min_ab_key="fantasy_market_min_ab",
        )
    except Exception:
        try:
            from shared_draft_context import on_alias_lookback_changed

            on_alias_lookback_changed(
                st.session_state, "fantasy_market_window", source_page="Fantasy Sleepers & Busts"
            )
        except Exception:
            pass
    try:
        force_save_baseball_state(st, reason="fantasy_filter_changed")
    except Exception:
        pass


if active_page == "Leaderboards":
    from leaderboard_aggregation import (
        aggregate_leaderboard_career_totals,
        build_leaderboard_aggregation_diagnostics,
        build_leaderboard_summary,
        filter_yearly_for_leaderboards,
    )
    from leaderboards_state import (
        flush_leaderboards_filter_edits,
        prepare_leaderboards_filters,
        prepare_leaderboards_page,
        prepare_leaderboards_year_range,
        render_leaderboards_state_debug,
    )

    prepare_leaderboards_page(st.session_state)
    prepare_leaderboards_filters(st.session_state)

    render_section_header("🏆 Leaderboards", "Build custom offensive rankings with weighted stats, filters, summary cards, and charts.")
    render_page_guide(active_page)
    apply_pending_page_transfer(active_page)
    leaders_sort_options = ["score", "R", "AB", "H", "2B", "3B", "HR", "RBI", "SB", "BB", "BA", "OBP", "SLG", "OPS"]
    c1, c2, c3 = st.columns([2, 1, 1])
    with c1:
        prepare_leaderboards_year_range(
            st.session_state,
            year_min,
            year_max,
            (max(year_min, 2020), year_max),
        )
        validate_slider_range(
            "leaders_year_range_filter",
            year_min,
            year_max,
            (max(year_min, 2020), year_max),
        )
        range_leaders = st.slider(
            "Select Year Range",
            min_value=year_min,
            max_value=year_max,
            key="leaders_year_range_filter",
            on_change=leaderboards_filter_changed,
        )
    with c2:
        init_state_once("leaders_top_n_filter", 25)
        top_n_leaders = st.slider(
            "Show Top N Players",
            min_value=5,
            max_value=100,
            key="leaders_top_n_filter",
            on_change=leaderboards_filter_changed,
        )
    with c3:
        validate_state_option("leaders_sort_stat_filter", leaders_sort_options, "score")
        sort_stat_leaders = st.selectbox(
            "Sort by",
            leaders_sort_options,
            key="leaders_sort_stat_filter",
            on_change=leaderboards_filter_changed,
        )

    weight_stats = ["R", "AB", "H", "2B", "3B", "HR", "RBI", "SB", "BB", "BA", "OBP", "SLG", "OPS"]
    _default_weights = {"HR": 1.0, "RBI": 1.0, "SB": 1.0}
    # Seed any missing weight keys from defaults before widgets render so that
    # Streamlit doesn't fall back to value= defaults and stomp user edits.
    for _ws in weight_stats:
        st.session_state.setdefault(f"leaders_w_{_ws}", _default_weights.get(_ws, 0.0))
    weight_values = {}
    with st.expander("Custom stat weights (defaults: HR / RBI / SB at 1.0; others 0)", expanded=False):
        st.caption("Weights feed the Score column only; raw counting and rate stats in the table are unchanged.")
        weight_cols = st.columns(4)
        for i, stat in enumerate(weight_stats):
            with weight_cols[i % 4]:
                weight_values[stat] = st.number_input(
                    f"Weight for {stat}",
                    min_value=0.0,
                    max_value=10.0,
                    step=0.5,
                    key=f"leaders_w_{stat}",
                    on_change=leaderboards_filter_changed,
                )

    _lb_agg_start = time.perf_counter()
    filtered_leaders = filter_yearly_for_leaderboards(yearly_df, range_leaders)
    leaderboard = aggregate_leaderboard_career_totals(filtered_leaders)
    st.session_state["_perf_leaderboard_agg_sec"] = round(time.perf_counter() - _lb_agg_start, 4)
    leaderboard = add_rate_stats(leaderboard)
    leaderboard = apply_stat_min_filters(leaderboard, "leaders", on_change=leaderboards_filter_changed)
    leaderboard = safe_round_rate_stats(leaderboard)

    leaderboard["score"] = 0.0
    for stat, weight in weight_values.items():
        leaderboard["score"] += weight * (leaderboard[stat] * 100 if stat in RATE_STATS else leaderboard[stat])

    top_bar_chart(leaderboard, "fullName", sort_stat_leaders, f"Top 10 by {sort_stat_leaders}")

    leaderboard_sorted = leaderboard.sort_values(sort_stat_leaders, ascending=False, na_position="last")
    leaderboard_display = leaderboard_sorted.head(top_n_leaders)[[
        "fullName", "bats", "R", "AB", "H", "2B", "3B", "HR", "RBI", "SB", "BB", "BA", "OBP", "SLG", "OPS", "score"
    ]].rename(columns={"fullName": "Player", "bats": "Bats", "score": "Score"})
    lb_summary = build_leaderboard_summary(
        leaderboard,
        sort_stat=sort_stat_leaders,
        displayed_count=len(leaderboard_display),
    )

    c12, c13, c14 = st.columns(3)
    c12.metric("Highest Score", lb_summary["highest_score"])
    c13.metric(lb_summary["category_leader_label"], lb_summary["category_leader"])
    c14.metric("Players Displayed", lb_summary["players_displayed"])

    st.divider()
    leaderboard_table = format_display_table(clean_ui_columns(leaderboard_display), count_cols=["R", "AB", "H", "2B", "3B", "HR", "RBI", "SB", "BB"], rate_cols=["BA", "OBP", "SLG", "OPS"], score_cols=["Score"])
    render_output_table(leaderboard_table, key="leaderboards", file_name="leaderboards.csv")
    _lb_xfer_df = (
        leaderboard.sort_values(sort_stat_leaders, ascending=False).head(top_n_leaders)
        if not leaderboard.empty
        else leaderboard
    )
    render_contextual_page_nav(
        "Leaderboards",
        "after_table",
        label="Use these filters in another tool…",
        transfer_results_df=_lb_xfer_df,
        transfer_name_col="fullName",
        default_rank_stat=sort_stat_leaders,
    )
    flush_leaderboards_filter_edits(st.session_state, st, reason="leaderboards_page_save")
    if developer_mode_enabled():
        render_leaderboards_state_debug(st, st.session_state)
        with st.expander("Leaderboard aggregation diagnostics", expanded=True):
            st.json(
                build_leaderboard_aggregation_diagnostics(
                    filtered_leaders,
                    leaderboard,
                    year_range=range_leaders,
                )
            )
    save_page_state(active_page)
    render_page_filters_debug(active_page)


